        ('BUET', 'demo.farhana.buet@campus360.test', 'fbd30b5b-6d50-5025-9393-e868b32c4eba'::uuid, 'skills', 'Looking for a partner for the National ICT Fest 2026', 'Team of one left for the ICT Fest mobile app track. Need someone comfortable with Flutter and Firebase. Problems are released two weeks before; we can start at the CSE lounge every Friday evening.', false, 18, 6, '3 hours'),
