        ('RU', 'demo.sumaiya.ru@campus360.test', 'af48cec8-9f79-54cf-ab8d-15dafed03fe8'::uuid, 'lost-found', U&'\09AA\09C1\099C\09BE \09AE\09BE\09B0\09CD\0995\09C7\099F\09C7 \099B\09BE\09A4\09CD\09B0\09C0\09B0 \0986\0987\09A1\09BF \0995\09BE\09B0\09CD\09A1 \09AA\09BE\0993\09AF\09BC\09BE \0997\09C7\099B\09C7', U&'\09B0\09BE\099C\09B6\09BE\09B9\09C0 \09AC\09BF\09B6\09CD\09AC\09AC\09BF\09A6\09CD\09AF\09BE\09B2\09AF\09BC\09C7\09B0 \098F\0995 \099B\09BE\09A4\09CD\09B0\09C0\09B0 \0986\0987\09A1\09BF \0995\09BE\09B0\09CD\09A1 \09AA\09C1\099C\09BE \09AE\09BE\09B0\09CD\0995\09C7\099F\09C7\09B0 \0995\09BE\099B\09C7 \09AA\09BE\0993\09AF\09BC\09BE \0997\09C7\099B\09C7 \2014 \09A8\09BE\09AE \09AE\09CC\09B8\09C1\09AE\09BF \0986\0995\09CD\09A4\09BE\09B0, \09E8\09E6\09E7\09EF \09AC\09CD\09AF\09BE\099A\0964 \09A8\09BF\099C\09C7\09B0 \09AA\09B0\09BF\099A\09AF\09BC \09A6\09BF\09AF\09BC\09C7 \09AC\09C1\099D\09C7 \09A8\09BF\09A4\09C7 \09B9\09AC\09C7; \09AE\09BE\09AE\09B2\09BE\09B0 \09AD\09AF\09BC \09A8\09AF\09BC, \09B8\09B0\09BE\09B8\09B0\09BF.security office-\098F \099C\09AE\09BE \09A6\09BF\09AF\09BC\09C7\099B\09BF\0964', false, 34, 3, '6 hours'),
        ('CU', 'demo.imran.cu@campus360.test', 'dd5a7716-b636-52a9-ac63-2c4330359e69'::uuid, 'housing', U&'Mess rent going up around Khulshi \2014 share your actual rate', U&'Landlords near Khulshi and Nurjahan Road are asking Tk 9,500\201311,000 for a 3-sharing room including utility. If you are paying materially different this term, put the real number in the housing module so juniors get a fair idea instead of guessing from Facebook groups.', false, 52, 27, '12 hours'),
        ('CU', 'demo.farzana.cu@campus360.test', '3fdf9bc3-3977-5a76-8ed4-ddce1439e0ec'::uuid, 'careers', U&'Referral slots for the Accounts intern intake \2014 Agrabad', 'My firm in Agrabad is taking four interns from CU Commerce for the spring intake (paid, Tk 12,000 a month). Send CV and transcript through the careers module and tick the referral box; the shortlist is reviewed every Sunday.', false, 74, 19, '1 day'),
        ('SUST', 'demo.rafiul.sust@campus360.test', '336d5c92-c70e-548f-bf32-9d15b5172de9'::uuid, 'general', U&'Sylhet rain forecast \2014 low-lying routes near Kumargaon', U&'Four days of heavy rain forecast for Sylhet. The Kumargaon road floods first, so plan 30 minutes extra for morning classes. Auto rickshaw drivers are charging Tk 60 instead of Tk 30 on that stretch \2014 report it to the transport office instead of paying silently.', true, 96, 41, '45 minutes'),
        ('SUST', 'demo.sabrina.sust@campus360.test', '7e556743-b835-51d6-8126-d20c0349b1ea'::uuid, 'events', 'Ayesha Siddiqa Hall night duty roster for exams', 'Hall administration will keep the gate open till 2:00am from 24 November during final exams. Entry/exit card is still required. Residents coming from outside Sylhet should inform the hall office a day earlier so the night duty roster is not broken.', false, 29, 5, '2 days'),
        ('JUST', 'demo.alamin.just@campus360.test', '58fa21ec-85d3-5e9e-afff-a62d29bce61c'::uuid, 'academics', 'Library entry for day scholars, and the question paper rack', U&'Central library entry for day-scholar students is open 09:00\201320:00 with the current session card. Copies of the last three years of CSE question papers are now on the second floor in the reference section \2014 no borrowing, scanning allowed with permission from the desk.', false, 37, 11, '9 hours'),
        ('JUST', 'demo.tahmina.just@campus360.test', '80149f4c-06d4-5a92-9277-7fa7e7be42a9'::uuid, 'donations', U&'\09B6\09C0\09A4 \09A8\09BF\09B0\09BE\09AA\09A4\09CD\09A4\09BE \09A4\09B9\09AC\09BF\09B2 \2014 \09A6\09BF\09A8\09AE\099C\09C1\09B0 \0993 \09A6\09BF\09A8\09B6\09BF\0995\09CD\09B7\09BE\09B0\09CD\09A5\09C0\09B0 \099C\09A8\09CD\09AF \0995\09AE\09CD\09AC\09B2', U&'\0989\09A4\09CD\09A4\09B0\09C7\09B0 \09B6\09C0\09A4\09C7 \099Cash\09CB\09B0\09C7\09B0 \0995\09CD\09AF\09BE\09AE\09CD\09AA\09BE\09B8\09C7 \09B0\09BE\09A4\09C7 \0995\09CD\09B2\09BE\09B8 \09B6\09C7\09B7\09C7 \09B8\09BE\0987\0995\09C7\09B2 \099A\09BE\09B2\09BF\09AF\09BC\09C7 \09AB\09C7\09B0\09BE \09B6\09BF\0995\09CD\09B7\09BE\09B0\09CD\09A5\09C0\09A6\09C7\09B0 \0995\09AE\09CD\09AC\09B2 \09AA\09CD\09B0\09AF\09BC\09CB\099C\09A8\0964 \0986\0997\09BE\09AE\09C0 \09E7\09EB \09A8\09AD\09C7\09AE\09CD\09AC\09B0 \09AA\09B0\09CD\09AF\09A8\09CD\09A4 \09A1\09CB\09A8\09C7\09B6\09A8 \09AE\09A1\09BF\0989\09B2\09C7 \09EB\09E6\09E6 \099F\09BE\0995\09BE \0995\09B0\09C7 \09AF\09CB\0997 \09A6\09BF\09B2\09C7 \09EA\09E6\099F\09BF \0995\09AE\09CD\09AC\09B2 \0995\09C7\09A8\09BE \09AF\09BE\09AC\09C7\0964 \09A4\09BE\09B2\09BF\0995\09BE \0993 \09B0\09B8\09BF\09A6 \09B9\09B2 \0985\09AB\09BF\09B8\09C7 \09B8\0982\09B0\0995\09CD\09B7\09BF\09A4 \09A5\09BE\0995\09AC\09C7\0964', false, 45, 7, '1 day')
  ) AS v(campus_code, author_email, id, tag, title, body, pinned, likes, comments, ago)
