  -- · events (6 rows)
  INSERT INTO public.events (id, university_id, organizer_id, host_organization, title_en, title_bn, description_en, description_bn, category, is_public, starts_at, ends_at, venue_name, formatted_address, text_directions_en, text_directions_bn, lat, lng, place_id, geofence_radius_m, capacity, rsvp_required, rsvp_limit, ticket_price_bdt, live_override, created_at)
  SELECT v.id, u.id, pr.id, v.org, v.title_en, v.title_bn, v.desc_en, v.desc_bn, v.cat, true, v.starts, v.ends, v.venue, v.addr, v.dirs_en, v.dirs_bn, v.lat, v.lng, 'campus360:demo:' || u.code || '-event', v.geo, v.cap, true, v.cap, 0, 'AUTO'::public.event_live_override, (now() - interval '4 days')
  FROM (VALUES
        ('DU', 'demo.tanvir.du@campus360.test', '540d5911-8abd-5c83-9b9c-6d2bf262ed51'::uuid, 'Dhaka University Computer Society', U&'DU Computer Society \2014 Web & Cloud Workshop 2026', U&'\09A1\09BF\0989 \0995\09AE\09CD\09AA\09BF\0989\099F\09BE\09B0 \09B8\09CB\09B8\09BE\0987\099F\09BF \2014 \0993\09AF\09BC\09C7\09AC \0993 \0995\09CD\09B2\09BE\0989\09A1 \0993\09AF\09BC\09BE\09B0\09CD\0995\09B6\09AA', 'One-day workshop on shipping a Next.js app with Postgres on a free tier. Bring a laptop. Two tracks: beginner (React basics) and advanced (CI/CD, edge functions). Lunch is arranged for registered participants only.', U&'\09B2\09CD\09AF\09BE\09AA\099F\09AA \09A8\09BF\09AF\09BC\09C7 \0986\09B8\09C1\09A8; \09A6\09C1\099F\09BF \099F\09CD\09B0\09CD\09AF\09BE\0995 \2014 \09AC\09BF\0997\09BF\09A8\09BE\09B0 (React) \0993 \0985\09CD\09AF\09BE\09A1\09AD\09BE\09A8\09CD\09B8\09A1 (CI/CD)\0964 \09A8\09BF\09AC\09A8\09CD\09A7\09BF\09A4\09A6\09C7\09B0 \099C\09A8\09CD\09AF \09A6\09C1\09AA\09C1\09B0\09C7\09B0 \0996\09BE\09AC\09BE\09B0\09C7\09B0 \09AC\09CD\09AF\09AC\09B8\09CD\09A5\09BE \09A5\09BE\0995\09AC\09C7\0964', 'Technology', (date_trunc('day', (now() + interval '6 days')) + interval '10 hours'), ((date_trunc('day', (now() + interval '6 days')) + interval '10 hours') + interval '6 hours'), 'TSC Auditorium, Dhaka University', 'Mirpur Road, Dhaka 1000', 'Enter through the TSC gate; the auditorium is on the second floor. Registration desk is at the staircase.', U&'\099F\09BF\098F\09B8\09B8\09BF \0997\09C7\099F \09A5\09C7\0995\09C7 \09A2\09C1\0995\09C1\09A8 \2014 \0985\09A1\09BF\099F\09CB\09B0\09BF\09AF\09BC\09BE\09AE \09A6\09CD\09AC\09BF\09A4\09C0\09AF\09BC \09A4\09B2\09BE\09AF\09BC, \09A8\09BF\09AC\09A8\09CD\09A7\09A8 \09A1\09C7\09B8\09CD\0995 \09B8\09BF\0981\09A1\09BC\09BF\09B0 \09AA\09BE\09B6\09C7\0964', 23.733, 90.3943, 180, 250),
        ('BUET', 'demo.sabbir.buet@campus360.test', '5f83bbf0-2ea9-5cf2-9a8c-9ef1815564e0'::uuid, 'BUET Debate Club', 'BUET National Inter-University Debate 2026', U&'\09AC\09BF\0987\0989\0987\099F\09BF \099C\09BE\09A4\09C0\09AF\09BC \0986\09A8\09CD\09A4\0983\09AC\09BF\09B6\09CD\09AC\09AC\09BF\09A6\09CD\09AF\09BE\09B2\09AF\09BC \09AC\09BF\09A4\09B0\09CD\0995 \09AA\09CD\09B0\09A4\09BF\09AF\09CB\0997\09BF\09A4\09BE \09E8\09E6\09E8\09EC', 'Bangla and English parliamentary debate with 32 teams. Preliminaries in the morning, final at 5:00pm in the main auditorium. Speakers from any department are welcome; the club runs practice rounds on campus every Tuesday.', NULL, 'Debate', (date_trunc('day', (now() + interval '9 days')) + interval '9 hours'), ((date_trunc('day', (now() + interval '9 days')) + interval '9 hours') + interval '8 hours'), 'BUET Auditorium', 'Sheikh Mizibur Rahman Road, Agargaon, Dhaka 1201', 'The auditorium is right inside gate 1; the registration desk is under the shade tree, look for the blue tent.', U&'\0997\09C7\099F \09E7-\098F \09A2\09C1\0995\09B2\09C7\0987 \0985\09A1\09BF\099F\09CB\09B0\09BF\09AF\09BC\09BE\09AE \2014 \09A8\09C0\09B2 \09A4\09BE\0981\09AC\09C1\09A4\09C7 \09A8\09BF\09AC\09A8\09CD\09A7\09A8 \09A1\09C7\09B8\09CD\0995\0964', 23.7873, 90.352, 150, 400),
        ('RU', 'demo.mehedi.ru@campus360.test', '06fa30bf-5327-54a3-a59a-b4107969a812'::uuid, 'Rajshahi University Career Club', U&'RU Career Fair 2026 \2014 Business & Engineering', U&'\0986\09B0\0987\0987 \0995\09CD\09AF\09BE\09B0\09BF\09AF\09BC\09BE\09B0 \09AB\09C7\09AF\09BC\09BE\09B0 \09E8\09E6\09E8\09EC', U&'Eighteen employers on campus, including bKash, BRAC, City Bank, Dutch-Bangla Bank and two software firms. Bring printed CVs \2014 twenty copies is a realistic number. Formal dress code; the CV review booth runs from 10:00am in the Senate Bhaban lobby.', U&'\09AA\09CD\09B0\09BF\09A8\09CD\099F \0995\09B0\09BE \09B8\09BF\09AD\09BF \09A8\09BF\09AF\09BC\09C7 \0986\09B8\09C1\09A8 (\09E8\09E6 \0995\09AA\09BF)\0964 \09B8\09BF\09AD\09BF \09B0\09BF\09AD\09BF\0989 \09AC\09C1\09A5 \09B8\0995\09BE\09B2 \09E7\09E6\099F\09BE \09A5\09C7\0995\09C7 \09B8\09BF\09A8\09C7\099F \09AD\09AC\09A8\09C7\09B0 \09B2\09AC\09BF\09A4\09C7\0964', 'Career', (date_trunc('day', (now() + interval '14 days')) + interval '10 hours'), ((date_trunc('day', (now() + interval '14 days')) + interval '10 hours') + interval '6 hours'), 'Senate Bhaban, Rajshahi University', 'Rajshahi 6205', 'Senate Bhaban is past the Administrative Building; parking is on the north side, three minutes on foot from the Motihar gate.', U&'\09AA\09CD\09B0\09B6\09BE\09B8\09A8\09BF\0995 \09AD\09AC\09A8\09C7\09B0 \09AA\09B0\09C7 \2014 \09AE\09CB\09A4\09BF\09B9\09BE\09B0 \0997\09C7\099F \09A5\09C7\0995\09C7 \09A4\09BF\09A8 \09AE\09BF\09A8\09BF\099F \09B9\09BE\0981\099F\09BE\0964', 24.3745, 89.0641, 120, 600),
        ('CU', 'demo.imran.cu@campus360.test', '803a6538-7dad-5055-89cb-467214ebde63'::uuid, 'CUET Hall Sports Committee', U&'CUET Inter-Hall Cricket Tournament \2014 group stage', U&'\099A\09BF\0989\0987\0987 \0987\09A8\09CD\099F\09BE\09B0-\09B9\09B2 \0995\09CD\09B0\09BF\0995\09C7\099F \099F\09C1\09B0\09CD\09A8\09BE\09AE\09C7\09A8\09CD\099F \2014 \0997\09CD\09B0\09C1\09AA \09AA\09B0\09CD\09AC', 'Twelve halls, knockout after the group stage. Ball and bat are provided by the hall sports committee; bring your own pads. Match one is A. F. Rahman Hall vs Masterda Surya Sen Hall at 9:00am on the central playground.', U&'\09AC\09B2 \0993 \09AC\09CD\09AF\09BE\099F \09B9\09B2 \0995\09CD\09B0\09C0\09A1\09BC\09BE \0995\09AE\09BF\099F\09BF \09A6\09C7\09AC\09C7; \09AA\09CD\09AF\09BE\09A1 \09B8\0999\09CD\0997\09C7 \0986\09A8\09A4\09C7 \09B9\09AC\09C7\0964', 'Sports', (date_trunc('day', (now() + interval '3 days')) + interval '9 hours'), ((date_trunc('day', (now() + interval '3 days')) + interval '9 hours') + interval '6 hours'), 'CU Central Playground', 'Kulagaon Road, Agrabad, Chattogram 4202', 'The playground is behind the CRB building; the entry gate is open to students with an ID card on match days.', U&'\09B8\09BF\0986\09B0\09AC\09BF \09AD\09AC\09A8\09C7\09B0 \09AA\09C7\099B\09A8\09C7 \2014 \09B6\09C1\09A7\09C1 \0986\0987\09A1\09BF \0995\09BE\09B0\09CD\09A1\09A7\09BE\09B0\09C0 \09B6\09BF\0995\09CD\09B7\09BE\09B0\09CD\09A5\09C0 \09AA\09CD\09B0\09AC\09C7\09B6 \0995\09B0\09AC\09C7\0964', 22.3509, 91.8549, 300, 1000),
        ('SUST', 'demo.rafiul.sust@campus360.test', 'ba6f3243-0a9c-5021-9545-ee0393cc3a9d'::uuid, 'SUST Innovation Club', 'SUST Innovation & Startup Expo 2026', U&'\09B8\09BE\09B8\09CD\099F \0989\09A6\09CD\09AD\09BE\09AC\09A8 \0993 \09B8\09CD\099F\09BE\09B0\09CD\099F\0986\09AA \098F\0995\09CD\09B8\09AA\09CB \09E8\09E6\09E8\09EC', 'Student teams demo products to investors and industry mentors. Forty stalls, and the best campus startup gets Tk 100,000 in seed support from the alumni network. Visitor registration closes the night before.', U&'\09EA\09E6\099F\09BF \09B8\09CD\099F\09B2; \09B8\09C7\09B0\09BE \0995\09CD\09AF\09BE\09AE\09CD\09AA\09BE\09B8 \09B8\09CD\099F\09BE\09B0\09CD\099F\0986\09AA\0995\09C7 \09AA\09CD\09B0\09BE\0995\09CD\09A4\09A8 \09B6\09BF\0995\09CD\09B7\09BE\09B0\09CD\09A5\09C0\09A6\09C7\09B0 \09A8\09C7\099F\0993\09AF\09BC\09BE\09B0\09CD\0995 \09A5\09C7\0995\09C7 \09E7,\09E6\09E6,\09E6\09E6\09E6 \099F\09BE\0995\09BE \09AC\09C0\099C \09A4\09B9\09AC\09BF\09B2\0964', 'Technology', (date_trunc('day', (now() + interval '20 days')) + interval '10 hours'), ((date_trunc('day', (now() + interval '20 days')) + interval '10 hours') + interval '7 hours'), 'SUST Auditorium, Kumargaon', 'Kumargaon, Thakagaon, Sylhet 3114', 'The auditorium is beside the Administrative Building. Stall holders should reach by 8:00am for setup.', U&'\09AA\09CD\09B0\09B6\09BE\09B8\09A8\09BF\0995 \09AD\09AC\09A8\09C7\09B0 \09AA\09BE\09B6\09C7 \2014 \09B8\09CD\099F\09B2 \09B9\09B2\09C7 \09B8\0995\09BE\09B2 \09EE\099F\09BE\09AF\09BC \09AA\09CC\0981\099B\09BE\09A8\0964', 24.8985, 91.8886, 200, 500),
        ('JUST', 'demo.alamin.just@campus360.test', '1d19f440-9464-5f46-b1a8-8155fd1837d3'::uuid, 'JUST Cultural Club', 'JUST Winter Cultural Night & Charity Stall', U&'\099C\0987\09B8\09CD\099F \09B6\09C0\09A4\0995\09BE\09B2\09C0\09A8 \09B8\09BE\0982\09B8\09CD\0995\09C3\09A4\09BF\0995 \09B8\09A8\09CD\09A7\09CD\09AF\09BE \0993 \09A6\09BE\09A8\09AC\09BE\099C\09BE\09B0', 'An evening of song, poetry and a drama by the Theatre Club, plus charity stalls raising money for blankets for day scholars. Rehearsals start this week in the seminar hall; the open mic list is limited to twenty names.', U&'\09A6\09BF\09A8\09B6\09BF\0995\09CD\09B7\09BE\09B0\09CD\09A5\09C0\09A6\09C7\09B0 \0995\09AE\09CD\09AC\09B2\09C7\09B0 \099C\09A8\09CD\09AF \09A6\09BE\09A8\09AC\09BE\099C\09BE\09B0 \099A\09B2\09AC\09C7; \0993\09AA\09C7\09A8 \09AE\09BE\0987\0995 \09A4\09BE\09B2\09BF\0995\09BE \09E8\09E6 \099C\09A8\09C7 \09B8\09C0\09AE\09BF\09A4\0964', 'Culture', (date_trunc('day', (now() + interval '11 days')) + interval '18 hours'), ((date_trunc('day', (now() + interval '11 days')) + interval '18 hours') + interval '4 hours'), 'JUST Seminar Hall, Central Library', 'Rajshahi Knowledge City, Jashore 7408', 'The seminar hall is on the third floor of the central library building. The lift is out of service, so stairs only.', U&'\0995\09C7\09A8\09CD\09A6\09CD\09B0\09C0\09AF\09BC \09B2\09BE\0987\09AC\09CD\09B0\09C7\09B0\09BF\09B0 \09A4\09C3\09A4\09C0\09AF\09BC \09A4\09B2\09BE \2014 \09B2\09BF\09AB\099F \09AC\09A8\09CD\09A7, \09B8\09BF\0981\09A1\09BC\09BF \09A6\09BF\09AF\09BC\09C7 \0989\09A0\09A4\09C7 \09B9\09AC\09C7\0964', 25.4545, 89.0662, 90, 300)
  ) AS v(campus_code, author_email, id, org, title_en, title_bn, desc_en, desc_bn, cat, starts, ends, venue, addr, dirs_en, dirs_bn, lat, lng, geo, cap)
  JOIN public.universities u ON u.code = v.campus_code
