        ('CU', 'demo.farzana.cu@campus360.test', '785688f2-707c-555c-b19f-48e21b21d73c'::uuid, 'Nasrin Akter', 'B+', 2, 'Chattagram Medical College Hospital', 'Khanjahara, Chattogram 4203', '+880 1819-220011', 'URGENT', '2 days', 'OPEN'),
