  -- · blood_request_responses (8 rows)
  INSERT INTO public.blood_request_responses (id, university_id, user_id, request_id, donor_id, message, status)
  SELECT v.id, u.id, pr.id, v.request_id::uuid, v.donor_id::uuid, v.message, v.status
  FROM (VALUES
        ('DU', 'demo.mehedi.ru@campus360.test', '178bc7a1-5d14-5925-bf91-da90efcc7f84'::uuid, 'e72ebe68-1f29-5f49-a17a-919847f945a6', 'b0c61fb9-7e83-5149-9f5e-f9dda7691246', 'ACCEPTED', U&'I am O- and free after 4pm. I will reach the DMC blood bank by 5:30pm \2014 please keep my name at the counter.'),
        ('DU', 'demo.sabbir.buet@campus360.test', 'a47159e8-7afe-5740-8d7a-86b6edb851cc'::uuid, 'e72ebe68-1f29-5f49-a17a-919847f945a6', 'bc927b26-f39f-5bdf-aa03-ebe3e8fc19c1', 'OFFERED', 'My roommate is O- and can come if you still need a second bag.'),
        ('CU', 'demo.imran.cu@campus360.test', '8b75d0bf-d7a0-54c3-802f-5226b5b2cdc8'::uuid, '785688f2-707c-555c-b19f-48e21b21d73c', 'e269734a-083f-5863-ae8a-6b97a721857a', 'ACCEPTED', 'B+ available tomorrow morning before my 10am class. Send the ward number so I do not wander the corridors.'),
        ('RU', 'demo.rafiul.sust@campus360.test', '11025d81-86c9-5b99-98d8-46d1a5d2a0ee'::uuid, '60cf334b-f306-5636-98f9-8235c0488d98', 'c2472f00-f1cb-5887-98af-7c448002e42f', 'OFFERED', NULL),
        ('JUST', 'demo.alamin.just@campus360.test', 'b7b6bf27-a7ba-52e9-9e76-31f6d3e8ef30'::uuid, 'be7e7a7c-b785-5032-a95e-458bb221a637', '1684bf83-41db-52a3-976a-2bd13736a3fd', 'ACCEPTED', 'Coming now with two batchmates from the CSE floor. Are you at the main gate or the emergency entrance?'),
        ('SUST', 'demo.farhana.buet@campus360.test', 'ef8ecb0f-6c92-51e5-8d3b-ffc30603ca18'::uuid, 'ee08ce36-7d89-5220-a86b-4a69ca30b9e1', '9a448f8a-0e68-5b55-b266-a54bd3f9dda3', 'DECLINED', U&'Sorry \2014 I donated on 12 September, so I have to wait another three months.'),
        ('SUST', 'demo.tanvir.du@campus360.test', 'ed823c70-6a67-561e-a33d-68f3936ff154'::uuid, 'ee08ce36-7d89-5220-a86b-4a69ca30b9e1', 'bedf053a-949d-5a4e-9681-52b1897feb40', 'ACCEPTED', 'Sunday 9am works. I will bring the donor card from my last donation at Shahjalal Medical.'),
        ('JUST', 'demo.nusrat.du@campus360.test', '672b5977-10bd-5189-865a-810b92cfb7b5'::uuid, 'be7e7a7c-b785-5032-a95e-458bb221a637', NULL, 'OFFERED', NULL)
  ) AS v(campus_code, author_email, id, request_id, donor_id, status, message)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  ON CONFLICT (id) DO UPDATE SET message = EXCLUDED.message, status = EXCLUDED.status;,

  -- · academic_files (12 rows)
  INSERT INTO public.academic_files (id, university_id, uploader_id, department_id, course_code, course_title, semester, academic_year, category, language, visibility, requires_same_university_verification, license_attribution, tags, current_version, storage_path, original_filename, mime_type, file_size_bytes, checksum_sha256, scan_status, views_count, downloads_count, upvotes_count, created_at, updated_at)
  SELECT v.id, u.id, pr.id, (select dp.id from public.departments dp where dp.university_id = u.id and dp.code = v.dept limit 1), v.course_code, v.course_title, v.semester, v.year, v.category::public.archive_category, v.language, v.visibility::public.content_visibility, (v.visibility <> 'PUBLIC'), U&'CC BY-NC 4.0 \2014 student-contributed material, not an official course document', v.tags, 2, 'archive/' || u.code || '/' || v.filename, v.filename, 'application/pdf', v.size, encode(digest(v.filename || u.code, 'sha256'), 'hex'), 'CLEAN'::public.virus_scan_status, v.views, v.downloads, greatest(1, v.downloads / 7), (now() - make_interval(days => v.age_days)), (now() - make_interval(days => v.age_days))
