        ('BUET', 'demo.sabbir.buet@campus360.test', '1cfa2bda-ebcc-5ddd-970d-5d4a58535e23'::uuid, 'EEE', 'EEE 211', U&'Electric Circuit I \2014 five years of mid terms and finals', 'Spring 2025', 2025, 'PAST_EXAMS', 'en', 'PUBLIC', ARRAY['circuits', 'Thevenin', 'past papers']::text[], 'eee-211-past-exams.pdf', 2191360, 5120, 2280, 40),
