        ('RU', 'demo.mehedi.ru@campus360.test', 'ca77bb90-00c9-5f07-b763-fc5cdc827bde'::uuid, 'CSE', 'CSE-3107', U&'Numerical Methods \2014 question bank and previous board questions', 'Spring 2025', 2025, 'QUESTION_BANKS', 'mixed', 'PRIVATE_TO_UNIVERSITY', ARRAY['numerical', 'question bank']::text[], 'cse-3107-question-banks.pdf', 655360, 1590, 703, 33),
        ('RU', 'demo.sumaiya.ru@campus360.test', '77d73ee3-2e77-50e2-bc49-d2a4c8a71cd7'::uuid, 'BENG', 'BENG-202', U&'\0986\09A7\09C1\09A8\09BF\0995 \0995\09AC\09BF\09A4\09BE \2014 \0985\09CD\09AF\09BE\09B8\09BE\0987\09A8\09AE\09C7\09A8\09CD\099F \09B0\09C1\09AC\09CD\09B0\09BF\0995 \0993 \09A8\09AE\09C1\09A8\09BE \0989\09A4\09CD\09A4\09B0', 'Fall 2025', 2026, 'ASSIGNMENTS', 'bn', 'PRIVATE_TO_UNIVERSITY', ARRAY[U&'\09B0\099A\09A8\09BE', U&'\09B0\09C1\09AC\09CD\09B0\09BF\0995', U&'\09A8\09AE\09C1\09A8\09BE']::text[], 'beng-202-assignments.pdf', 317440, 940, 388, 5),
        ('CU', 'demo.imran.cu@campus360.test', 'a071614b-42e6-5376-b8a2-bc08b0592d81'::uuid, 'EEE', 'EEE 101', U&'Engineering Mechanics \2014 reference notes (Meriam chapters 1-4 summary)', 'Spring 2025', 2025, 'REFERENCE_BOOKS', 'en', 'PUBLIC', ARRAY['mechanics', 'summary']::text[], 'eee-101-reference-books.pdf', 1802240, 4180, 1655, 51),
