        ('SUST', 'demo.rafiul.sust@campus360.test', '26c9e7f9-66c5-5253-ac67-6afc6bde490d'::uuid, 'CSE', 'CSE 3105', U&'Object Oriented Programming (Java) \2014 sessional guide and rubric', 'Spring 2026', 2026, 'ASSIGNMENTS', 'en', 'PRIVATE_TO_UNIVERSITY', ARRAY['Java', 'OOP', 'sessional']::text[], 'cse-3105-assignments.pdf', 1208320, 2740, 1120, 17),
        ('SUST', 'demo.sabrina.sust@campus360.test', '1ea718dd-1dc4-56c3-a4a8-5312fbd429b3'::uuid, 'IPE', 'IPE 301', 'Thermal Engineering Lab Manual (boiler trial, report format)', 'Fall 2024', 2025, 'LAB_MANUALS', 'mixed', 'PRIVATE_TO_UNIVERSITY', ARRAY['thermo', 'lab report']::text[], 'ipe-301-lab-manuals.pdf', 1556480, 1980, 745, 62),
        ('JUST', 'demo.alamin.just@campus360.test', 'f8321d28-ec13-5525-ae88-f1862d44c862'::uuid, 'BBA', 'BBA 1101', U&'Principles of Marketing \2014 course outline and evaluation sheet', 'Fall 2025', 2026, 'COURSE_OUTLINES', 'en', 'PUBLIC', ARRAY['outline', 'marks']::text[], 'bba-1101-course-outlines.pdf', 98304, 260, 511, 7),
        ('JUST', 'demo.tahmina.just@campus360.test', 'a2502bd8-d05e-5765-af6a-37eece66f27e'::uuid, 'CHEM', 'CHEM 101', U&'\099C\09C8\09AC \09B0\09B8\09BE\09AF\09BC\09A8 \09B2\09CD\09AF\09BE\09AC \0993 \09A5\09BF\09B8\09BF\09B8 \09AA\09CD\09B0\0995\09B2\09CD\09AA \09AA\09CD\09B0\09A4\09BF\09AC\09C7\09A6\09A8\09C7\09B0 \09A8\09AE\09C1\09A8\09BE (\09E8\09E6\09E8\09EA)', 'Spring 2024', 2024, 'THESIS_PROJECT_REPORTS', 'bn', 'PRIVATE_TO_UNIVERSITY', ARRAY[U&'\09A5\09BF\09B8\09BF\09B8', U&'\09A8\09AE\09C1\09A8\09BE', U&'\099C\09C8\09AC \09B0\09B8\09BE\09AF\09BC\09A8']::text[], 'chem-101-thesis-project-reports.pdf', 2027520, 3610, 1298, 88)
  ) AS v(campus_code, author_email, id, dept, course_code, course_title, semester, year, category, language, visibility, tags, filename, size, views, downloads, age_days)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
