  -- · skill_postings (12 rows)
  INSERT INTO public.skill_postings (id, university_id, author_id, type, title, description, category, skills, location_en, location_bn, availability, rate_bdt, is_remote, contact_note, status, applicants_count, created_at, updated_at)
  SELECT v.id, u.id, pr.id, v.typ::public.skill_posting_type, v.title, v.descr, v.cat, v.skills, v.loc_en, v.loc_bn, v.avail, v.rate, v.remote, v.contact, v.status, v.applicants, (now() - make_interval(hours => v.age_hours)), (now() - make_interval(hours => v.age_hours))
  FROM (VALUES
        ('DU', 'demo.tanvir.du@campus360.test', '94b27ba8-17b3-5922-b465-9df16d0c2942'::uuid, 'TUTORING', 'HSC and admission Math & Physics tutor (Dhanmondi / Mirpur)', 'Three years with HSC students from the Dhaka and Savar boards, plus admission batches for Engineering and Medical. I take at most two subjects per student so doubt-clearing does not get rushed. First class is free if you tell me the syllabus a day earlier.', 'Tutoring', ARRAY['Mathematics', 'Physics', 'Admission Test', 'HSC']::text[], 'Dhanmondi 27, Dhaka', U&'\09A7\09BE\09A8\09AE\09A8\09CD\09A1\09BF \09E8\09ED, \09A2\09BE\0995\09BE', 'EVENINGS', 1200, false, 'WhatsApp 01712-345678 after 6pm', 'OPEN', 3, 5),
        ('DU', 'demo.nusrat.du@campus360.test', '6484bec9-cffb-5f5f-ba9a-857cb2e51d24'::uuid, 'FREELANCE', 'Bangla and English content writing for club events and pages', 'I write event copies, poster text and Facebook page content for three DU clubs this term. Comfortable in both Bangla and English, and I keep a proofread checklist so nobody prints a typo on a programme poster. Two revisions included.', 'Content Writing', ARRAY['Bangla', 'Copywriting', 'Proofreading', 'Canva']::text[], 'Anywhere (online)', U&'\0985\09A8\09B2\09BE\0987\09A8', 'FLEXIBLE', 350, true, U&'Send the deadline with the brief \2014 48 hours notice minimum', 'OPEN', 2, 11),
        ('BUET', 'demo.sabbir.buet@campus360.test', 'a92605d7-b4d1-5edb-b3c8-328c4dd5e6c2'::uuid, 'PART_TIME_JOB', 'Junior frontend developer (part-time) at an EdTech startup', U&'Our team of five needs one part-time React developer for the student dashboard \2014 roughly 15 hours a week, classes first always. Stack is Next.js, Tailwind and REST. Paid monthly, and work can move to the campus library if your hosteling makes remote unreliable.', 'Development', ARRAY['React', 'Next.js', 'Tailwind', 'Git']::text[], 'Mirpur DOHS, Dhaka (hybrid)', U&'\09AE\09BF\09B0\09AA\09C1\09B0 \09A1\09BF\0993\098F\0987\099A\098F\09B8', 'WEEKDAYS', 15000, true, 'Send a GitHub link or one deployed site; no CV needed', 'OPEN', 3, 26),
        ('BUET', 'demo.farhana.buet@campus360.test', 'f7e8c12a-04cf-5e37-8ee1-b48a084fc4be'::uuid, 'INTERNSHIP', U&'Research assistant intern \2014 power systems data cleaning', 'Paid internship under a BUET EEE faculty project on load forecasting: mostly MATLAB and Excel with some Python. Good for second and third year EEE/ECE students who want a publication line on the CV. Twelve weeks, ten hours a week.', 'Research', ARRAY['MATLAB', 'Python', 'Excel', 'Data Cleaning']::text[], 'EEE Room 305, BUET', U&'\0987\0987\0987 \09AC\09BF\09AD\09BE\0997, \09AC\09C1\0987\0987\099F\09BF', 'WEEKENDS', 12000, false, 'Transcript plus one line on which courses you have completed', 'OPEN', 5, 33),
        ('RU', 'demo.mehedi.ru@campus360.test', 'd8a9bfd1-e1eb-564e-8d98-abbc3813e31c'::uuid, 'TUTORING', 'Spoken English & IELTS crash course for RU students', 'Evening batch of eight at the Kazla reading room, 6:00-7:30pm. Speaking practice every class, plus Writing Task 1 and 2 feedback. I got Band 7.5 and I teach the strategies that worked for me, not the generic advice. Materials included.', 'Tutoring', ARRAY['IELTS', 'Speaking', 'Writing', 'Grammar']::text[], 'Kazla, Rajshahi', U&'\0995\09BE\099C\09B2\09BE, \09B0\09BE\099C\09B6\09BE\09B9\09C0', 'EVENINGS', 800, false, U&'Trial class this Thursday 6pm \2014 just come to the reading room', 'OPEN', 3, 8),
        ('RU', 'demo.sumaiya.ru@campus360.test', '7206c8d3-126a-5299-8652-5800790aa85b'::uuid, 'FREELANCE', 'Poster and social media design (proper Bangla typography)', 'Event posters, farewell and birthday covers with correct Bangla font handling (SolaimanLipi / Noto, converted so nothing breaks in print). You get a print-ready PDF and a square feed version per design, with outlines included.', 'Design', ARRAY['Photoship', 'Illustrator', 'Bangla Typography', 'Print Ready']::text[], 'Anywhere (online)', U&'\0985\09A8\09B2\09BE\0987\09A8', 'FLEXIBLE', 400, true, 'Tell me the hall poster size if the office requires a specific one', 'OPEN', 2, 47),
        ('CU', 'demo.imran.cu@campus360.test', 'ed085748-a3ee-510f-ae94-0c671a5e0942'::uuid, 'TUTORING', 'O-Level Physics & Math home tutor (Agrabad / Khulshi)', 'Cambridge O-Level Physics and D2 Math, plus SSC students who need mechanics explained slowly. I keep a mistake notebook per student because that is what actually fixes exam panic rather than more lectures. Two evenings a week available.', 'Tutoring', ARRAY['Physics', 'Mathematics', 'O-Level', 'SSC']::text[], 'Agrabad, Chattogram', U&'\0986\0997\09CD\09B0\09BE\09AC\09BE\09A6, \099A\099F\09CD\099F\0997\09CD\09B0\09BE\09AE', 'EVENINGS', 6000, false, 'Parents may call 01819-220011 between 4pm and 8pm', 'OPEN', 1, 20),
        ('CU', 'demo.farzana.cu@campus360.test', 'aac24643-b4f6-5537-b0d5-393e87d1ba4c'::uuid, 'PART_TIME_JOB', 'Accounts & VAT filing assistant (paid internship, Agrabad)', 'Back-office work for a small audit firm near Agrabad Chowmuhani: data entry into Tally, VAT challan filing and bank reconciliation. Twenty hours a week. Right if you do Accounting at CU and want real filing experience before graduation.', 'Business', ARRAY['Tally', 'MS Excel', 'VAT Filing', 'Reconciliation']::text[], 'Agrabad CDA Avenue, Chattogram', U&'\0986\0997\09CD\09B0\09BE\09AC\09BE\09A6 \09B8\09BF\09A1\09BF\098F\098F\09AD\09BF\09A8\09BF\0989, \099A\099F\09CD\099F\0997\09CD\09B0\09BE\09AE', 'WEEKDAYS', 10000, false, U&'CV required \2014 Sunday shortlist, starting the following Monday', 'OPEN', 6, 71),
        ('SUST', 'demo.rafiul.sust@campus360.test', 'ddfbbb7b-231e-5621-9cb4-73b4a451e875'::uuid, 'TUTORING', 'Programming tutor for SUST 1st/2nd year (C and Python)', 'Problem-solving sessions in the Shah Paran Hall common room for Data Structures and elementary programming. We solve past sessional questions, not theory slides. If pointers or recursion are what is hurting you, that is exactly where we start.', 'Tutoring', ARRAY['C', 'Python', 'Data Structures', 'Problem Solving']::text[], 'Zindabazar / Shah Paran Hall, Sylhet', U&'\099C\09BF\09A8\09CD\09A6\09BE\09AC\09BE\099C\09BE\09B0, \09B8\09BF\09B2\09C7\099F', 'FLEXIBLE', 1000, false, 'Message me the topic; I will say honestly whether I can teach it', 'OPEN', 7, 14),
        ('SUST', 'demo.sabrina.sust@campus360.test', '40548b4c-9ae9-5c5e-8a7e-577ad2706d44'::uuid, 'FREELANCE', 'Video editing for club documentaries and YouTube', 'Premiere Pro and DaVinci Resolve. I cut the SUST fest aftermovie and four club documentaries, so I know how to keep a hall event video watchable instead of twelve minutes of shaky clips. Colour, Bangla and English subtitles and a thumbnail included.', 'Design', ARRAY['Premiere Pro', 'DaVinci Resolve', 'Subtitles', 'Thumbnails']::text[], 'Anywhere (online)', U&'\0985\09A8\09B2\09BE\0987\09A8', 'WEEKENDS', 4000, true, 'Share raw footage on Drive; 48 hours per 10 minutes of footage', 'OPEN', 3, 60),
        ('JUST', 'demo.alamin.just@campus360.test', 'f93b3faa-2521-56ca-99ef-96fb39b5af1a'::uuid, 'PART_TIME_JOB', 'Data entry & digital archive assistant (Knowledge City)', U&'Digitising department records into Google Sheets and the university archive for the JUST ICT office. Bangla typing speed matters more than anything else here \2014 around 25 wpm is enough. Morning or evening, whatever fits your timetable.', 'Data', ARRAY['Bangla Typing', 'Google Sheets', 'Scanning', 'Record Keeping']::text[], 'JUST Administrative Building', U&'\099C\0987\09B8\09CD\099F \09AA\09CD\09B0\09B6\09BE\09B8\09A8\09BF\0995 \09AD\09AC\09A8', 'MORNING', 9000, false, 'Bring a sample of Bangla typing if you have one', 'OPEN', 2, 90),
        ('JUST', 'demo.tahmina.just@campus360.test', '8f8ae1f8-545d-5081-a6a5-efb16abc566d'::uuid, 'TUTORING', U&'\098F\09B8\098F\09B8\09B8\09BF \0993 \098F\0987\099A\098F\09B8\09B8\09BF \09AA\09B0\09C0\0995\09CD\09B7\09BE\09B0\09CD\09A5\09C0\09A6\09C7\09B0 \0986\0987\09B8\09BF\099F\09BF \0993 \09AA\09A6\09BE\09B0\09CD\09A5\09AC\09BF\099C\09CD\099E\09BE\09A8 \099F\09BF\0989\09B6\09A8', U&'\099Cash\09CB\09B0 \09B6\09B9\09B0\09C7 \09AE\09BE\09A4\09CD\09B0 \09A6\09C1\0987\099C\09A8 \09B6\09BF\0995\09CD\09B7\09BE\09B0\09CD\09A5\09C0 \09A8\09C7\09AC\0964 \09AA\09CD\09B0\09A4\09BF\09A6\09BF\09A8 \09B8\09A8\09CD\09A7\09CD\09AF\09BE \09EB\099F\09BE \09A5\09C7\0995\09C7 \09ED\099F\09BE, \09AC\09C3\09B9\09B8\09CD\09AA\09A4\09BF\09AC\09BE\09B0 \099B\09C1\099F\09BF\0964 \09AA\09C1\09B0\09A8\09CB \09AA\09CD\09B0\09B6\09CD\09A8\09AA\09A4\09CD\09B0 \09B8\09AE\09BE\09A7\09BE\09A8 \0993 \09B2\09BF\0996\09BF\09A4 \0985\0982\09B6\09C7\09B0 \09AA\09CD\09B0\09CD\09AF\09BE\0995\099F\09BF\09B8 \0995\09B0\09BE\09A8\09CB \09B9\09AF\09BC\0964 \09AA\09CD\09B0\09A5\09AE \0995\09CD\09B2\09BE\09B8\099F\09BF \09AB\09CD\09B0\09BF \2014 \09AA\09A1\09BC\09BE\09A8\09CB\09B0 \09A7\09B0\09A8 \09AC\09C1\099D\09C7 \09A4\09BE\09B0\09AA\09B0 \09B8\09BF\09A6\09CD\09A7\09BE\09A8\09CD\09A4 \09A8\09BF\09A8\0964', 'Tutoring', ARRAY['ICT', 'Physics', 'SSC', 'HSC']::text[], 'Fazlatun, Jashore', U&'\09AB\099C\09B2\09A4\09C1\09A8, \09AF\09B6\09CB\09B0', 'EVENINGS', 700, false, U&'\0985\09AD\09BF\09AD\09BE\09AC\0995 \09AB\09CB\09A8 \0995\09B0\09AC\09C7\09A8 \09E6\09E7\09EF\09E9\09E9-\09EA\09E6\09EA\09E6\09EA\09E6 (\09B8\0995\09BE\09B2 \09E7\09E6\099F\09BE\2013\09B0\09BE\09A4 \09EF\099F\09BE)', 'CLOSED', 0, 150)
  ) AS v(campus_code, author_email, id, typ, title, descr, cat, skills, loc_en, loc_bn, avail, rate, remote, contact, status, applicants, age_hours)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, skills = EXCLUDED.skills, location_en = EXCLUDED.location_en, location_bn = EXCLUDED.location_bn, availability = EXCLUDED.availability, rate_bdt = EXCLUDED.rate_bdt, is_remote = EXCLUDED.is_remote, contact_note = EXCLUDED.contact_note, status = EXCLUDED.status, applicants_count = EXCLUDED.applicants_count, updated_at = EXCLUDED.updated_at;,

  -- · skill_applications (10 rows)
  INSERT INTO public.skill_applications (id, university_id, applicant_id, posting_id, message, status, created_at)
  SELECT v.id, u.id, pr.id, v.posting_id::uuid, v.message, v.status, (now() - interval '6 hours')
  FROM (VALUES
        ('BUET', 'demo.farhana.buet@campus360.test', 'd09c69b8-e5ad-5877-8e6f-dd1b04833f2f'::uuid, 'a92605d7-b4d1-5edb-b3c8-328c4dd5e6c2', 'SENT', 'Second year CSE. I have one deployed React site and I know Tailwind basics. I can start next week and I am serious about the fifteen hours.'),
        ('SUST', 'demo.rafiul.sust@campus360.test', '5bdb9eb6-f2f4-52d7-8d29-5731d8e10073'::uuid, '94b27ba8-17b3-5922-b465-9df16d0c2942', 'SHORTLISTED', 'I took your admission batch last year. If it helps, I can run doubt-clearing for the junior section on Fridays.'),
        ('SUST', 'demo.sabrina.sust@campus360.test', '329f789b-6790-51ac-8fb8-3eba02772ab3'::uuid, 'ddfbbb7b-231e-5621-9cb4-73b4a451e875', 'ACCEPTED', U&'I need Data Structures help before sessionals \2014 Tuesday and Thursday 6pm works for me.'),
        ('JUST', 'demo.alamin.just@campus360.test', 'fb92bac9-0fa1-5cff-b442-8b5101040c65'::uuid, 'd8a9bfd1-e1eb-564e-8d98-abbc3813e31c', 'SENT', NULL),
        ('DU', 'demo.tanvir.du@campus360.test', '79e56b8b-3b69-5f94-8cae-3e43db02c8e2'::uuid, '6484bec9-cffb-5f5f-ba9a-857cb2e51d24', 'DECLINED', 'Sorry, I already have two students this term and I would do a bad job of a third.'),
        ('CU', 'demo.imran.cu@campus360.test', 'd56306e3-ff07-5121-bfa4-a4927b9f3a13'::uuid, 'aac24643-b4f6-5537-b0d5-393e87d1ba4c', 'ACCEPTED', 'Third year Accounting. I used Tally for two months in my uncle''s firm and I can work Sundays.'),
        ('RU', 'demo.mehedi.ru@campus360.test', '2e60e5c7-cf1b-5804-9d65-515b0d55c4bc'::uuid, '7206c8d3-126a-5299-8652-5800790aa85b', 'SENT', U&'Our hall magazine needs three posters \2014 can you send two sample designs first?'),
        ('DU', 'demo.nusrat.du@campus360.test', 'eb34c8ea-aac6-55d1-877d-7d2839816e09'::uuid, 'f7e8c12a-04cf-5e37-8ee1-b48a084fc4be', 'SHORTLISTED', NULL),
        ('BUET', 'demo.sabbir.buet@campus360.test', '11acbb2d-15a6-5f66-909c-ad27f83c445d'::uuid, 'f7e8c12a-04cf-5e37-8ee1-b48a084fc4be', 'SENT', '2nd year EEE. MATLAB is part of my coursework and Saturday-Sunday mornings are free.'),
        ('JUST', 'demo.tahmina.just@campus360.test', '3af918d0-6d49-5448-8b13-6e6ba7b891eb'::uuid, 'f93b3faa-2521-56ca-99ef-96fb39b5af1a', 'ACCEPTED', 'I can take the archive entry work on Wednesdays and Fridays from the library.')
  ) AS v(campus_code, author_email, id, posting_id, status, message)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  ON CONFLICT (id) DO UPDATE SET message = EXCLUDED.message, status = EXCLUDED.status;,

  -- · skill_alerts (6 rows)
  INSERT INTO public.skill_alerts (id, university_id, user_id, keywords, categories)
  SELECT v.id, u.id, pr.id, v.kw, v.cats
  FROM (VALUES
        ('DU', 'demo.tanvir.du@campus360.test', '736f4c04-43fd-549a-a196-d37671b9a33c'::uuid, ARRAY['React', 'Next.js', 'frontend']::text[], ARRAY['Development']::text[]),
        ('BUET', 'demo.farhana.buet@campus360.test', '2bcad799-c103-5f3b-a241-e85a53effbb3'::uuid, ARRAY['MATLAB', 'research', 'internship']::text[], ARRAY['Research', 'Internship']::text[]),
        ('RU', 'demo.mehedi.ru@campus360.test', '4ce183fe-30a9-5e38-8050-aec2b85afa91'::uuid, ARRAY['IELTS', 'speaking', 'English']::text[], ARRAY['Tutoring']::text[]),
        ('CU', 'demo.imran.cu@campus360.test', 'ee8d5683-4a54-5200-bb2d-194e0ef212f9'::uuid, ARRAY['Tally', 'accounts', 'VAT']::text[], ARRAY['Business']::text[]),
        ('SUST', 'demo.rafiul.sust@campus360.test', 'f020eb65-3bea-571c-8e45-2d88e6476391'::uuid, ARRAY['Python', 'DSA', 'sessional']::text[], ARRAY['Tutoring', 'Development']::text[]),
        ('JUST', 'demo.alamin.just@campus360.test', '9d388608-da0b-5b98-8367-83957359c2fa'::uuid, ARRAY['typing', 'data entry', 'archive']::text[], ARRAY['Data']::text[])
  ) AS v(campus_code, author_email, id, kw, cats)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  ON CONFLICT (id) DO UPDATE SET keywords = EXCLUDED.keywords, categories = EXCLUDED.categories;,

  -- · mentor_profiles (3 rows)
  INSERT INTO public.mentor_profiles (id, university_id, user_id, headline, expertise, languages, session_rate_bdt, bio, is_accepting, sessions_count, rating)
  SELECT v.id, u.id, pr.id, v.headline, v.exp, ARRAY['Bangla', 'English']::text[], v.rate, v.bio, true, v.sessions, v.rating
  FROM (VALUES
        ('DU', 'demo.shahriar.mentor@campus360.test', 'af8b04c0-f4ae-5791-b93f-57a9069c9512'::uuid, U&'Final-year English, DU \2014 admission and placement preparation', ARRAY['Admission Test', 'Interview Prep', 'English', 'CV Review']::text[], 0, 'I sat three admission tests in one season and got into DU, so I can walk you through a realistic timetable instead of a motivational one. I also review freshers'' CVs and I am blunt about which lines a recruiter skips.', 23, 4.8),
        ('BUET', 'demo.tanjila.mentor@campus360.test', 'ed168fad-ddf8-534d-887b-b138f4edd339'::uuid, U&'MTE graduate, BUET \2014 thesis, research and higher studies abroad', ARRAY['Thesis', 'GRE / IELTS', 'Scholarship Applications', 'MATLAB']::text[], 0, 'Third-year MTE with two conference papers. I mentor on choosing a supervisor, surviving a thesis deadline and the scholarship paperwork for Germany and Canada. I will read your SOP and tell you which paragraph is filler.', 14, 4.6),
        ('SUST', 'demo.arsalan.mentor@campus360.test', '83d7b342-990f-5ab0-a38e-965bd5c2cb44'::uuid, U&'CSE final year, SUST \2014 DSA roadmap and starting freelancing', ARRAY['DSA', 'Freelancing', 'React', 'Interview Prep']::text[], 300, '900+ online judge problems solved, and I have been freelancing since my second year, so both the interview path and the client path are open to me. Sessions are practical: we solve together, you get homework, we review it.', 41, 4.9)
  ) AS v(campus_code, author_email, id, headline, exp, rate, bio, sessions, rating)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  ON CONFLICT (id) DO UPDATE SET headline = EXCLUDED.headline, expertise = EXCLUDED.expertise, languages = EXCLUDED.languages, session_rate_bdt = EXCLUDED.session_rate_bdt, bio = EXCLUDED.bio, is_accepting = EXCLUDED.is_accepting, sessions_count = EXCLUDED.sessions_count, rating = EXCLUDED.rating;,

  -- · mentorship_slots (8 rows)
  INSERT INTO public.mentorship_slots (id, university_id, mentor_id, topic, starts_at, ends_at, capacity, booked_count, is_active)
  SELECT v.id, u.id, (select mp.id from public.mentor_profiles mp where mp.university_id = u.id and mp.user_id = (select p9.id from public.profiles p9 where p9.email = v.author_email limit 1) limit 1), v.topic, (date_trunc('hour', now() + v.day_off::interval) + make_interval(hours => v.hhour)), (date_trunc('hour', now() + v.day_off::interval) + make_interval(hours => v.hhour + 1)), v.capacity, v.booked, true
  FROM (VALUES
        ('DU', 'demo.shahriar.mentor@campus360.test', 'a55e80d2-3b7a-5c7c-9310-8b7c2a2e6919'::uuid, 'CV line-by-line review for freshers applications', '2 days', 20, 1, 1),
        ('DU', 'demo.shahriar.mentor@campus360.test', '2a539e81-c312-58fe-a262-fe9d55456dc6'::uuid, 'Admission math drill: functions and limits', '4 days', 18, 2, 0),
        ('DU', 'demo.shahriar.mentor@campus360.test', 'b5aa7e2d-58a8-58a3-ab99-bbe8ba4f52fe'::uuid, 'IELTS speaking part 2 practice with feedback', '6 days', 19, 1, 0),
        ('BUET', 'demo.tanjila.mentor@campus360.test', 'd628801d-f074-5396-9766-28f5756d85c2'::uuid, 'Choosing a thesis supervisor (what I wish I knew)', '3 days', 21, 1, 1),
        ('BUET', 'demo.tanjila.mentor@campus360.test', '4545f4ce-22a7-58c5-b757-5928b28b16a8'::uuid, U&'SOP writing workshop \2014 bring a draft', '7 days', 19, 1, 0),
        ('SUST', 'demo.arsalan.mentor@campus360.test', 'c89ea3fb-387d-5d1c-b487-8a7a7c339c6f'::uuid, 'DSA mock interview (45 minutes, live coding)', '2 days', 17, 1, 0),
        ('SUST', 'demo.arsalan.mentor@campus360.test', 'eda12748-e347-5bb7-aca0-9bda1118ce3f'::uuid, 'Getting a first freelance client without underselling', '5 days', 20, 1, 1),
        ('SUST', 'demo.arsalan.mentor@campus360.test', '3279a9cc-bee3-5164-88ad-7b182f01e51b'::uuid, 'Graph problems: the BFS/DFS patterns that repeat', '9 days', 21, 2, 0)
  ) AS v(campus_code, author_email, id, topic, day_off, hhour, capacity, booked)
  JOIN public.universities u ON u.code = v.campus_code
  ON CONFLICT (id) DO UPDATE SET topic = EXCLUDED.topic, starts_at = EXCLUDED.starts_at, ends_at = EXCLUDED.ends_at, capacity = EXCLUDED.capacity, booked_count = EXCLUDED.booked_count, is_active = EXCLUDED.is_active;,

  -- · housing_listings (6 rows)
  INSERT INTO public.housing_listings (id, university_id, author_id, kind, title, description, rent_bdt, seat_count, gender_policy, area_en, area_bn, distance_km, amenities, image_urls, contact_phone, status, created_at)
  SELECT v.id, u.id, pr.id, v.kind::public.housing_kind, v.title, v.descr, v.rent, v.seats, v.gender, v.area_en, v.area_bn, v.dist, v.amen, '{}'::text[], v.phone, v.status, (now() - interval '2 days')
  FROM (VALUES
        ('DU', 'demo.nusrat.du@campus360.test', '7ca7547e-446c-5d01-bed9-84158ac2fb58'::uuid, 'MESS_SEAT', 'Girls'' mess seat, two-sharing near Mirpur 10', 'Registered mess for DU and Jahangirnagar women students, fourth floor with a working lift. Two-sharing room, terrace cooking allowed, and the mess committee posts the monthly accounts on the notice board. ID card and a guardian''s number required before moving in.', 6500, 2, 'FEMALE', 'Mirpur 10, Dhaka', U&'\09AE\09BF\09B0\09AA\09C1\09B0 \09E7\09E6, \09A2\09BE\0995\09BE', 1.2, ARRAY['WiFi', 'Geyser', 'Terrace cooking', 'CCTV', 'Mess accounts published']::text[], '+880 1715-660011', 'AVAILABLE'),
        ('BUET', 'demo.sabbir.buet@campus360.test', 'e2d9da33-5a75-579a-9e65-0e68f7db5c46'::uuid, 'SUB_LET', 'Sub-let: 2BHK flat near Zinda Bazar (January to June)', 'I am going away for an internship term, so the flat is sublet for six months. Furnished: bed, almirah, study table, fridge and AC in the main room. The landlord already knows, and will re-sign in your name if you want to stay longer.', 18000, 1, 'ANY', 'Zinda Bazar, Agargaon, Dhaka', U&'\099C\09BF\09A8\09CD\09A6\09BE\09AC\09BE\099C\09BE\09B0, \0986\0997\09BE\09B0\0997\09BE\0981\0993, \09A2\09BE\0995\09BE', 0.6, ARRAY['Furnished', 'AC', 'Fridge', 'Generator backup', 'Parking']::text[], '+880 1811-223344', 'AVAILABLE'),
        ('RU', 'demo.mehedi.ru@campus360.test', '081dd37b-9fe5-58df-9d66-62d08af44e26'::uuid, 'MESS_SEAT', U&'Male mess bed at Kazla \2014 three sharing, food included', 'Empty bed in a running RU mess; food is arranged by the mess itself (breakfast, packed lunch, dinner). Utility is included up to a limit. See the room before deciding: the fan in the south bed is dying, and I would rather say so here than have you find out.', 4500, 1, 'MALE', 'Kazla, Rajshahi', U&'\0995\09BE\099C\09B2\09BE, \09B0\09BE\099C\09B6\09BE\09B9\09C0', 0.9, ARRAY['Food included', 'WiFi', 'Study table', 'Rooftop drying']::text[], '+880 1911-556677', 'AVAILABLE'),
        ('CU', 'demo.farzana.cu@campus360.test', 'a353b19d-17b0-5849-8854-9d4bdc937ec2'::uuid, 'PAYING_GUEST', U&'PG room for women students \2014 Khulshi, quiet building', 'PG in a three-family building for CU Commerce students. Attached bath, hot water, and the owner cooks dinner so you do not have to run a mess. Curfew is 10pm, which suits my parents as much as it suits me, so I put it in the listing instead of hiding it.', 9000, 1, 'FEMALE', 'Khulshi, Chattogram', U&'\0996\09C1\09B2\09B6\09C0, \099A\099F\09CD\099F\0997\09CD\09B0\09BE\09AE', 2.4, ARRAY['Attached bath', 'Dinner included', 'Hot water', 'Wardrobe', 'Study table']::text[], '+880 1819-220011', 'AVAILABLE'),
        ('SUST', 'demo.rafiul.sust@campus360.test', '572f2ed1-bbfa-5d35-9c2d-c6a2215d0faf'::uuid, 'MESS_SEAT', 'Single-bed room at Sersotole for SUST students', 'Small but proper single room on the third floor, walking distance to the main gate. Rent excludes utility; the meter is shared with two other rooms and we split it monthly in a WhatsApp thread with photos of the bill, which has ended every argument so far.', 7500, 1, 'ANY', 'Sersotole, Sylhet', U&'\09B8\09BE\09B0\09B8\09CB\09A4\09B2, \09B8\09BF\09B2\09C7\099F', 0.7, ARRAY['Single room', 'Balcony', 'WiFi', 'Bill shared with proof']::text[], '+880 1722-101010', 'AVAILABLE'),
        ('JUST', 'demo.tahmina.just@campus360.test', '51989b33-6ef1-58ec-af94-bbf270f13e4c'::uuid, 'FAMILY_FLAT', U&'Ground-floor flat for a small family or two students \2014 Fazlatun', 'Flat with a separate entrance, its own kitchen and one covered parking space, next to the medical store. The landlord lives upstairs and is reasonable about repairs. Suitable for two sisters, or a postgraduate student with family.', 11500, 2, 'FEMALE', 'Fazlatun, Jashore', U&'\09AB\099C\09B2\09A4\09C1\09A8, \09AF\09B6\09CB\09B0', 1.6, ARRAY['Separate entrance', 'Own kitchen', 'Parking', 'Ground floor', 'Mosque nearby']::text[], '+880 1933-404040', 'AVAILABLE')
  ) AS v(campus_code, author_email, id, kind, title, descr, rent, seats, gender, area_en, area_bn, dist, amen, phone, status)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  ON CONFLICT (id) DO UPDATE SET kind = EXCLUDED.kind, title = EXCLUDED.title, description = EXCLUDED.description, rent_bdt = EXCLUDED.rent_bdt, seat_count = EXCLUDED.seat_count, gender_policy = EXCLUDED.gender_policy, area_en = EXCLUDED.area_en, area_bn = EXCLUDED.area_bn, distance_km = EXCLUDED.distance_km, amenities = EXCLUDED.amenities, image_urls = EXCLUDED.image_urls, contact_phone = EXCLUDED.contact_phone, status = EXCLUDED.status;,

  -- · rideshare_offers (6 rows)
  INSERT INTO public.rideshare_offers (id, university_id, author_id, mode, origin, destination, depart_at, seats_total, seats_available, fare_bdt, vehicle_details, notes, status, created_at)
  SELECT v.id, u.id, pr.id, v.mode::public.ride_mode, v.origin, v.dest, (now() + v.depart::interval), v.total, v.avail, v.fare, v.vehicle, (v.title || chr(10) || v.notes), v.status, (now() - interval '5 hours')
  FROM (VALUES
        ('DU', 'demo.tanvir.du@campus360.test', '272904b1-3be1-51b3-9cde-b0b46a3143e4'::uuid, 'CARPOOL', U&'Mirpur 10 to Nilphamar (DU gate) \2014 3 seats, morning', 'Mirpur 10 Bus Stand (opposite Shah Ali Mosque)', 'Dhaka University Central Students'' Hall (TSC)', '2 hours', 4, 3, 120, U&'Toyota Aqua \2014 \09A2\09BE\0995\09BE MA-KA 1123', 'Leaves exactly on time. One suitcase fits in the trunk; no smoking inside the car.', 'OPEN'),
        ('BUET', 'demo.farhana.buet@campus360.test', '43a9c33b-1856-5d1e-988c-1599df2be80f'::uuid, 'CARPOOL', 'Farmgate to BUET Gate 3 morning carpool (Sun-Thu)', 'Farmgate, Mirpur Avenue side', 'BUET Gate 3, Sheikh Mizibur Rahman Road', '1 day', 4, 4, 60, U&'Nissan Sunny \2014 \09A2\09BE\0995\09BE BA-1122 (2019, AC works)', 'Four seats including the driver, so three students split fuel. I drive; the fare is the petrol share, not profit.', 'FULL'),
        ('RU', 'demo.mehedi.ru@campus360.test', 'b23020fd-92fd-59c6-bf2d-5952cd8a09c5'::uuid, 'BUS', 'Motihar Hall gate to Puja Market shared CNG (evening)', 'Motihar Hall Main Gate, RU', 'Rajshahi Puja Market Bus Stand', '3 hours', 3, 2, 20, U&'Easy CNG, green plate \2014 driver Imrul (01711-000022)', 'Usually leaves 6:15pm after the hall library closes. Two more can join if seats are free.', 'OPEN'),
        ('CU', 'demo.imran.cu@campus360.test', 'ea700d9a-16a7-5353-abfc-bb2ab5b99b97'::uuid, 'MICROBUS', 'Agrabad to CU main gate via CRB (morning microbus share)', 'Agrabad CDA Avenue 2 No. Bus Stop', 'Chittagong University Main Gate, Kulagaon Road', '1 day', 12, 5, 25, 'Chattogram University Shomoy (white board on the windscreen)', 'Student rate Tk 25, general passengers pay Tk 40. Departs Agrabad at 8:00am sharp.', 'OPEN'),
        ('SUST', 'demo.rafiul.sust@campus360.test', 'e05adcd7-bab4-5261-8d48-3ce542d39014'::uuid, 'TRAIN', U&'Sylhet to Rajshahi overnight train \2014 sharing the station taxi', 'Sylhet Railway Station', 'Rajshahi Railway Station (then JUST campus van)', '5 days', 2, 2, 950, 'Parbat Express, coach GA, seats 12 and 13', 'I have two berths and need one person to split the station-to-campus CNG. Ticket is booked in my name; bring your NID for the ticket check.', 'OPEN'),
        ('JUST', 'demo.alamin.just@campus360.test', '63977817-5c88-503b-93c4-89ecaf6ba1d4'::uuid, 'BUS', 'Jashore road entry to JUST campus gate (rickshaw share, morning)', 'Jashore Bus Stand (new)', 'JUST Campus Gate, Fazlatun', '2 days', 4, 3, 40, 'Two rickshaws; van-rickshaw for luggage', 'Meets the 7:40am bus from Kushtia. If the bus is late we wait at the stand, not on the road.', 'OPEN')
  ) AS v(campus_code, author_email, id, mode, title, origin, dest, depart, total, avail, fare, vehicle, notes, status)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  ON CONFLICT (id) DO UPDATE SET mode = EXCLUDED.mode, origin = EXCLUDED.origin, destination = EXCLUDED.destination, depart_at = EXCLUDED.depart_at, seats_total = EXCLUDED.seats_total, seats_available = EXCLUDED.seats_available, fare_bdt = EXCLUDED.fare_bdt, vehicle_details = EXCLUDED.vehicle_details, notes = EXCLUDED.notes, status = EXCLUDED.status;,

  -- · alumni_profiles (6 rows)
  INSERT INTO public.alumni_profiles (id, university_id, user_id, graduation_year, degree, employer, job_title, industry, city, country, linkedin_url, offers_referrals, is_mentor)
  SELECT v.id, u.id, pr.id, v.year, v.degree, v.employer, v.title, v.industry, v.city, 'Bangladesh', v.linkedin, v.refs, v.mentor
  FROM (VALUES
        ('DU', 'demo.mahmudul.alumni@campus360.test', '3a1f1e7f-a45c-5dcb-853c-93c27ecc5c4a'::uuid, 2018, U&'MBA in Accounting \2014 DU', 'bKash', 'Senior Manager, Financial Operations', 'Fintech', 'Dhaka', 'https://www.linkedin.com/in/demo-alumni-du-2018', true, true),
        ('BUET', 'demo.sadia.alumni@campus360.test', 'f9cc59b4-562e-556d-b0bf-0e62f1ccecf5'::uuid, 2019, U&'B.Sc. in CSE \2014 BUET', 'Pathao', 'Backend Engineer (Go)', 'Software', 'Dhaka', 'https://www.linkedin.com/in/demo-alumni-buet-2019', true, true),
        ('RU', 'demo.nayeem.alumni@campus360.test', 'b24e282b-5273-5e82-8ac2-0e301ec5e9ec'::uuid, 2017, U&'B.A. (Honours) in Economics \2014 RU', 'Dutch-Bangla Bank PLC', 'Assistant VP, SME Credit', 'Banking', 'Rajshahi', 'https://www.linkedin.com/in/demo-alumni-ru-2017', true, false),
        ('CU', 'demo.rumana.alumni@campus360.test', '636998c7-25fc-5a85-844e-41499cab083b'::uuid, 2020, U&'M.Sc. in Finance \2014 CU', 'BRAC', 'Research Officer, Urban Health', 'Development', 'Chattogram', 'https://www.linkedin.com/in/demo-alumni-cu-2020', false, true),
        ('SUST', 'demo.kamrul.alumni@campus360.test', 'e02f2f57-3a90-58ca-a885-f5496ab823b5'::uuid, 2016, U&'B.Sc. in IPE \2014 SUST', 'Summit Group', 'Deputy Manager, Power Plant Operations', 'Energy', 'Sylhet', 'https://www.linkedin.com/in/demo-alumni-sust-2016', true, true),
        ('JUST', 'demo.sharmin.alumni@campus360.test', '7e517439-4a36-5d33-a600-ecb54a5e558c'::uuid, 2021, U&'BBA \2014 JUST', 'Grameenphone', 'Associate, Digital Marketing', 'Telecom', 'Dhaka', 'https://www.linkedin.com/in/demo-alumni-just-2021', true, true)
  ) AS v(campus_code, author_email, id, year, degree, employer, title, industry, city, linkedin, refs, mentor)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  ON CONFLICT (id) DO UPDATE SET graduation_year = EXCLUDED.graduation_year, degree = EXCLUDED.degree, employer = EXCLUDED.employer, job_title = EXCLUDED.job_title, industry = EXCLUDED.industry, city = EXCLUDED.city, country = EXCLUDED.country, linkedin_url = EXCLUDED.linkedin_url, offers_referrals = EXCLUDED.offers_referrals, is_mentor = EXCLUDED.is_mentor;,

  -- · career_opportunities (6 rows)
  INSERT INTO public.career_opportunities (id, university_id, alumni_id, kind, company, title, description, location, is_remote, salary_range, apply_url, deadline, status, created_at)
  SELECT v.id, u.id, (select ap.id from public.alumni_profiles ap where ap.university_id = u.id and ap.user_id = (select p9.id from public.profiles p9 where p9.email = v.author_email limit 1) limit 1), v.kind::public.career_opportunity_kind, v.company, v.title, v.descr, v.loc, v.remote, v.salary, v.url, (current_date + v.due::interval)::date, v.status, (now() - interval '3 days')
  FROM (VALUES
        ('DU', 'demo.mahmudul.alumni@campus360.test', '00067866-7410-5d26-9082-9063ed032e3f'::uuid, 'REFERRAL', 'bKash', 'Software Engineer I (referral by Mahmudul Hasan, DU 2018)', U&'Two openings on my team for graduates who can write SQL properly and are not frightened of a legacy Java service. I forward CVs to the hiring manager myself, which beats the portal queue \2014 but send one CV, not five versions of it.', 'Dhaka (Motijheel office)', false, 'BDT 90,000 - 140,000', 'https://www.bkash.com/en/careers', '21 days', 'OPEN'),
        ('BUET', 'demo.sadia.alumni@campus360.test', '0224803e-bec3-58e5-a51f-8e906310a751'::uuid, 'FULL_TIME', 'Pathao', U&'Backend Engineer (Go) \2014 Mobility Platform', 'We are splitting the ride-matching monolith, so this is real distributed-systems work rather than CRUD. If you have shipped a service with graceful degradation under load, tell me which part was hard. Relocation help is available from Sylhet or Chattogram.', 'Dhaka (Banani)', false, 'BDT 120,000 - 190,000', 'https://pathao.com/careers', '14 days', 'OPEN'),
        ('RU', 'demo.nayeem.alumni@campus360.test', '1d3c1889-25b0-50ee-a93b-853371fb70ab'::uuid, 'INTERNSHIP', 'Dutch-Bangla Bank PLC', U&'Graduate Management Trainee Officer (GMTO) \2014 2026 batch', 'Six months of paid training with branch rotation and a real appraisal at the end. For RU and north-zone students: the written test is English plus arithmetic under time pressure, and the interview mostly checks whether you know what a CRR is. I can share the pattern, never the answers.', 'Rajshahi / Dhaka', false, 'BDT 60,000 stipend', 'https://www.dutchbanglabank.com/Careers', '30 days', 'OPEN'),
        ('CU', 'demo.rumana.alumni@campus360.test', 'c1230869-8436-5bc3-8733-f1c1c9a2c906'::uuid, 'PART_TIME', 'BRAC', U&'Research Assistant (Urban Health) \2014 part-time', 'Data collection and cleaning for a maternal-health study in Chattogram city corporations. Twenty hours a week: fieldwork on Tuesdays and Thursdays, and you will learn REDCap properly. Suited to CU public health, statistics or economics students.', 'Chattogram', false, 'BDT 22,000 per month', 'https://www.brac.net/career', '10 days', 'OPEN'),
        ('SUST', 'demo.kamrul.alumni@campus360.test', '6c8cb449-b93a-5d46-a056-c1d71ee42948'::uuid, 'CONTRACT', 'Summit Group', 'Junior SCADA & Automation Engineer (12-month contract)', 'Plant-floor contract role with an extension possible. Day shift with some night calls when a trip happens. If you are a SUST IPE or EEE student who is not bothered by turbine noise, this is where you actually learn control systems instead of reading about them.', 'Sylhet (power plant)', false, 'BDT 65,000 - 80,000', 'https://www.summitgroup.org/career', '18 days', 'OPEN'),
        ('JUST', 'demo.sharmin.alumni@campus360.test', 'ef698dec-2b1e-5b4c-97f5-0c7c0cbee076'::uuid, 'REFERRAL', 'Grameenphone', 'Associate, Digital Marketing (referral by Sharmin Nahar, JUST 2021)', U&'GP''s graduate intake for the digital team. I can put a word after the assessment, not before it. Do the online test seriously \2014 that is the stage most applicants skip. Meta or Google certifications help but are not required.', 'Dhaka (Banani)', true, 'BDT 75,000 - 95,000', 'https://www.grameenphone.com/careers', '25 days', 'OPEN')
  ) AS v(campus_code, author_email, id, kind, company, title, descr, loc, remote, salary, url, due, status)
  JOIN public.universities u ON u.code = v.campus_code
  ON CONFLICT (id) DO UPDATE SET kind = EXCLUDED.kind, company = EXCLUDED.company, title = EXCLUDED.title, description = EXCLUDED.description, location = EXCLUDED.location, is_remote = EXCLUDED.is_remote, salary_range = EXCLUDED.salary_range, apply_url = EXCLUDED.apply_url, deadline = EXCLUDED.deadline, status = EXCLUDED.status;,

