        ('SUST', 'demo.rafiul.sust@campus360.test', 'a7b4b260-6607-5816-8f5d-6403fd90b36b'::uuid, U&'Shah Paran Hall Mess \2014 Lunch', 'Rui fish curry', U&'\09AE\09BE\099B \09AD\09B0\09CD\09A4\09BE (\09B0\09C1\0987)', 55, true, false),
        ('SUST', 'demo.rafiul.sust@campus360.test', 'c7bbac49-62b9-5fb1-bedd-deb95a9f12d7'::uuid, U&'Shah Paran Hall Mess \2014 Lunch', 'Aloo bhorta', U&'\0986\09B2\09C1 \09AD\09B0\09CD\09A4\09BE', 8, true, true),
        ('SUST', 'demo.rafiul.sust@campus360.test', '5afcd1d8-d630-56d2-b6bf-77e609542da1'::uuid, U&'Shah Paran Hall Mess \2014 Lunch', 'Seasonal fruit', U&'\09AE\09CC\09B8\09C1\09AE\09BF \09AB\09B2', 10, true, true),
        ('JUST', 'demo.alamin.just@campus360.test', '8dd2a783-cc3e-5ca8-bb9c-fb62a36d369a'::uuid, U&'JUST Central Cafeteria \2014 Lunch', 'Rice with chicken curry', U&'\099A\09BF\0995\09C7\09A8 \0995\09BE\09B0\09BF \09AD\09BE\09A4', 80, true, false),
        ('JUST', 'demo.alamin.just@campus360.test', '4acb7a96-006e-5016-b91d-e475924a2b20'::uuid, U&'JUST Central Cafeteria \2014 Lunch', 'Vegetable khichuri', U&'\09B8\09AC\099C\09BF \0996\09BF\099A\09C1\09A1\09BC\09BF', 60, true, true),
        ('JUST', 'demo.alamin.just@campus360.test', 'd4bc8959-569d-524d-8adc-545430588ca0'::uuid, U&'JUST Central Cafeteria \2014 Lunch', 'Bottle water', U&'\09AA\09BE\09A8\09BF\09B0 \09AC\09CB\09A4\09B2', 15, true, true),
        ('JUST', 'demo.alamin.just@campus360.test', 'aded77eb-2aee-50b5-86a5-80939eefd254'::uuid, U&'JUST Central Cafeteria \2014 Lunch', 'Yogurt', U&'\09A6\0987', 20, true, true)
  ) AS v(campus_code, author_email, id, menu, name_en, name_bn, price, avail, veg)
  JOIN public.universities u ON u.code = v.campus_code
  ON CONFLICT (id) DO UPDATE SET name_en = EXCLUDED.name_en, name_bn = EXCLUDED.name_bn, price_bdt = EXCLUDED.price_bdt, is_available = EXCLUDED.is_available, is_vegetarian = EXCLUDED.is_vegetarian;,

  -- · lost_items (6 rows)
  INSERT INTO public.lost_items (id, university_id, author_id, kind, title, description, category, keywords, location_en, occurred_on, image_urls, contact_note, status, created_at)
  SELECT v.id, u.id, pr.id, v.kind::public.lost_item_kind, v.title, v.descr, v.cat, v.kw, v.loc, (current_date - make_interval(days => v.age_days)), '{}'::text[], v.contact, v.status, (now() - make_interval(days => v.age_days))
  FROM (VALUES
        ('DU', 'demo.nusrat.du@campus360.test', '2c7e873c-87c3-5242-8eb5-291fce34cddb'::uuid, 'LOST', U&'DU student ID card \2014 CSE third year', U&'My university ID is missing since Saturday evening; last used at the central library issue counter. There is a photo on the card. If you found it, please hand it to the library desk or message me \2014 I need it for the exam form submission.', 'ID Card', ARRAY['DU ID', 'library', 'CSE']::text[], 'Central Library, Dhaka University', 2, 'Call 01712-345678, or leave it at the library return desk with my name.', 'OPEN'),
        ('DU', 'demo.tanvir.du@campus360.test', '143cfe1c-860c-5953-b6d4-0854fb067cc1'::uuid, 'FOUND', 'Casio fx-991EX calculator near the TSC shade', 'Found a black scientific calculator on the TSC bench yesterday evening. There is no name inside the cover, so it goes back to whoever can describe the sticker on the battery lid. Keeping it with me until the exam starts.', 'Gadget', ARRAY['calculator', 'Casio', 'TSC']::text[], 'TSC, Dhaka University', 1, 'Tell me the sticker or the mark on the case and it is yours.', 'OPEN'),
        ('BUET', 'demo.farhana.buet@campus360.test', '4a4ff5bc-40cd-5dc9-91fa-89ee7170537c'::uuid, 'LOST', 'Blue steel bottle and a key pouch (CSE lounge to hall gate)', U&'Lost a light blue steel bottle with a small cloth pouch holding my room key and two locker keys. It probably fell off the bicycle between the CSE lounge and the hall gate. Please return the keys \2014 I will pay for a new set, I only need the locker one.', 'Keys', ARRAY['keys', 'bottle', 'hall locker']::text[], 'CSE Lounge to Sher-e-Bangla Hall gate, BUET', 1, 'Leave it with the hall gate guard for Farhana, Sony Hall fourth floor.', 'OPEN'),
        ('RU', 'demo.mehedi.ru@campus360.test', 'd44bf45d-5aa6-50af-ab6f-8f82b7702bd0'::uuid, 'FOUND', U&'Men''s wallet with NIC and a bKash card \2014 Puja Market', 'Found a brown wallet near the Puja Market tea stall with a NIC and a bKash card inside. Cash is untouched and I have not counted it in front of anyone. State the name on the NIC and I will hand it over at the RU Security Office with a written record.', 'Wallet', ARRAY['wallet', 'NIC', 'Puja Market']::text[], 'Puja Market, Rajshahi', 3, 'Handover only at the RU Security Office after a description matches.', 'OPEN'),
        ('CU', 'demo.imran.cu@campus360.test', '0b902486-66a2-52ed-b86d-45d2ee646f74'::uuid, 'LOST', 'Grey laptop sleeve with the Data Structures notebook inside', 'Left my laptop sleeve on the third floor of the CRB building during the break: grey with a red zip, and inside is a hand-written Data Structures notebook that matters more to me than the laptop. Please check under the chairs near the stairway.', 'Bag', ARRAY['laptop sleeve', 'notebook', 'CRB']::text[], 'CRB Building third floor, CU', 2, 'Call 01819-220011 any time; reward for the notebook.', 'OPEN'),
        ('SUST', 'demo.rafiul.sust@campus360.test', 'bcfd4c9d-f3ae-5d6a-a9b9-e001f713167c'::uuid, 'FOUND', 'Red Phoenix bicycle locked near Ayesha Siddiqa Hall gate', 'A red Phoenix cycle has been locked to the same pole outside Ayesha Siddiqa Hall gate since 21 October with nobody claiming it. I reported it to the hall office and they asked me to post it here too, because students go home for Eid and forget cycles.', 'Cycle', ARRAY['Phoenix', 'cycle', 'Ayesha Siddiqa Hall']::text[], 'Ayesha Siddiqa Hall gate, SUST', 13, 'Claim at the hall office with the lock key and the purchase token.', 'OPEN')
  ) AS v(campus_code, author_email, id, kind, title, descr, cat, kw, loc, age_days, contact, status)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  ON CONFLICT (id) DO UPDATE SET kind = EXCLUDED.kind, title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, keywords = EXCLUDED.keywords, location_en = EXCLUDED.location_en, occurred_on = EXCLUDED.occurred_on, image_urls = EXCLUDED.image_urls, contact_note = EXCLUDED.contact_note, status = EXCLUDED.status;,

  -- · sports_challenges (6 rows)
  INSERT INTO public.sports_challenges (id, university_id, author_id, team_name, sport, title, description, preferred_date, venue, status, created_at)
  SELECT v.id, u.id, pr.id, v.team, v.sport, v.title, v.descr, (now() + v.doff::interval), v.venue, v.status, (now() - interval '7 hours')
  FROM (VALUES
        ('DU', 'demo.tanvir.du@campus360.test', '01bfa357-2107-5a26-9a69-4e2984a8efb9'::uuid, 'DU Cricket Club', 'Cricket', 'Ten-over challenge: DU CC open to any campus team', 'We are one bowler short and looking for a full side for Sunday morning at the central playground. New ball, our umpire, tea break after five overs. Tell me your strongest batter honestly so we do not end up with a forty-run game.', '5 days', 'DU Central Playground', 'OPEN'),
        ('BUET', 'demo.sabbir.buet@campus360.test', 'ce039b78-f529-5ae6-a1d2-f24bcf70a8fc'::uuid, 'Shahid Smriti Hall Football XI', 'Football', U&'Five-a-side football at the BUET indoor \2014 Sunday 4pm', 'Three players needed to close the squad, from any hall. We play 4pm to 6pm and split the court fee. Boots are useful because the artificial grass is worn on one side.', '3 days', 'BUET Sports Complex', 'OPEN'),
        ('RU', 'demo.mehedi.ru@campus360.test', '316d2408-206b-5a7e-9f1a-b19b1194df92'::uuid, 'RU Badminton Group', 'Badminton', U&'Doubles challenge \2014 court 2, RU Sports Club', 'Open doubles challenge for RU students, mixed pairs allowed. Two shuttlecocks per team; the court is booked till 8pm and the losing side buys tea. Last week fourteen people came for four courts, so come early or wait on the second list.', '2 days', 'Rajshahi University Sports Club', 'ACCEPTED'),
        ('CU', 'demo.imran.cu@campus360.test', 'eb63394d-b7a7-5993-8473-7434353e91c8'::uuid, 'CUET Table Tennis Team', 'Table Tennis', U&'Inter-hall table tennis open challenge \2014 seeding Saturday', U&'The hall sports committee seeds the open draw on Saturday at 10am in the indoor stadium. Registration is Tk 30 and it goes to the new-nets fund. If you can hold a bat straight, come \2014 the inter-hall trophy has sat in A. F. Rahman Hall for two years.', '4 days', 'CU Indoor Stadium', 'OPEN'),
        ('SUST', 'demo.rafiul.sust@campus360.test', 'b400c010-b73d-55f5-9063-d2c0c8bab474'::uuid, 'Shah Paran Hall Cricket', 'Cricket', U&'Sunday 3pm at North Field \2014 net session, need eleven', 'We need eleven and three bowlers who will actually run in. Bring your own bat if you have one; we have three spare bats and a box of balls. Also looking for a scorer who can keep a scorebook without arguing about no-balls.', '2 days', 'SUST North Field', 'PLAYED'),
        ('JUST', 'demo.alamin.just@campus360.test', '44d2ca0b-ca22-5d02-b3dd-95f8078ca1a2'::uuid, 'JUST Football Friends', 'Football', 'Seven-side friendly at Knowledge City ground', 'Open to every department; if the numbers are uneven we mix the teams on the spot. Goalkeeper is fixed for us this time. Bring a team from another JUST club? Message me first so we can book the ground properly.', '6 days', 'Rajshahi Knowledge City Ground', 'OPEN')
  ) AS v(campus_code, author_email, id, team, sport, title, descr, doff, venue, status)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  ON CONFLICT (id) DO UPDATE SET team_name = EXCLUDED.team_name, sport = EXCLUDED.sport, title = EXCLUDED.title, description = EXCLUDED.description, preferred_date = EXCLUDED.preferred_date, venue = EXCLUDED.venue, status = EXCLUDED.status;,

  -- · sports_teams (6 rows)
  INSERT INTO public.sports_teams (id, university_id, author_id, name, sport, skill_level, needed_roles, description, contact_note, status, created_at)
  SELECT v.id, u.id, pr.id, v.name, v.sport, v.level::text, v.roles, v.descr, v.contact, v.status, (now() - interval '3 days')
  FROM (VALUES
        ('DU', 'demo.tanvir.du@campus360.test', '3ecbd8f9-843a-5475-bfc9-e85f430174cd'::uuid, 'DUCC selection trial squad', 'Cricket', 'INTERMEDIATE', ARRAY['Opening batter', 'Left-arm pacer', 'Wicket-keeper']::text[], U&'Trials for the DUCC third team. Practice Tuesday and Thursday at 4pm on the central playground. Mention any inter-college tournament you have played \2014 that is the only thing separating the two lists right now.', 'Any time after 4pm on practice days', 'OPEN'),
        ('BUET', 'demo.farhana.buet@campus360.test', 'b35d7305-5723-5124-ad16-3769f08bf847'::uuid, 'Sony Hall futsal team', 'Futsal', 'BEGINNER', ARRAY['Two pivots', 'Backup keeper']::text[], 'Hall-level futsal on Wednesdays and Saturdays. Beginners welcome, because half of us learned the offside rule at the last hall fest. We split the court fee among whoever shows up, so turning up is more useful than being good.', 'Saturdays 5pm', 'OPEN'),
        ('RU', 'demo.mehedi.ru@campus360.test', '6ac7b873-7b42-5222-8d0a-88cf219bed35'::uuid, 'RU chess & badminton evening group', 'Badminton', 'ANY', ARRAY['Doubles partners', 'Shuttle sponsor']::text[], 'We are not a club, just twenty students who play every evening. I need two people who can commit to doubles because I keep running out of partners halfway through the session.', 'Evenings before 8pm', 'OPEN'),
        ('CU', 'demo.imran.cu@campus360.test', 'c0066038-6705-59f0-878e-767508161beb'::uuid, 'CUET volleyball team', 'Volleyball', 'INTERMEDIATE', ARRAY['Libero', 'Opposite hitter']::text[], U&'University team selection from the hall tournament list. We run on the sand court behind CRB \2014 bring shoes you do not mind, and water, because there is no tap at that end.', 'Sunday and Wednesday 3pm', 'FULL'),
        ('SUST', 'demo.sabrina.sust@campus360.test', 'b2e2962f-8a81-52e3-919b-55f99a14dfe5'::uuid, 'IPE night runners', 'Athletics', 'ANY', ARRAY['Pacers at 6 min/km']::text[], 'Not a team, a running group: five kilometres around the SUST lake at 6:30pm before it gets dark. Anyone who can hold a six-minute pace for two of the three loops is useful as a pacer, and that is the only requirement.', 'Daily 6:30pm', 'OPEN'),
        ('JUST', 'demo.tahmina.just@campus360.test', 'b2b3f04b-64b0-5bd4-ab5d-1d7cef8b5a49'::uuid, 'JUST women''s badminton', 'Badminton', 'BEGINNER', ARRAY['Two more regulars', 'A coach if you know one']::text[], 'JUST women students only; court time is booked on Thursday evenings. We are four and we want six so we can play doubles without borrowing partners from the men''s list.', 'Thursday 5-7pm', 'OPEN')
  ) AS v(campus_code, author_email, id, name, sport, level, roles, descr, contact, status)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, sport = EXCLUDED.sport, skill_level = EXCLUDED.skill_level, needed_roles = EXCLUDED.needed_roles, description = EXCLUDED.description, contact_note = EXCLUDED.contact_note, status = EXCLUDED.status;,

  -- · donation_campaigns (6 rows)
  INSERT INTO public.donation_campaigns (id, university_id, author_id, title, story, cause, target_bdt, raised_bdt, donors_count, deadline, cover_image_url, is_verified, status, created_at)
  SELECT v.id, u.id, pr.id, v.title, v.story, v.cause, v.target, v.raised, v.donors, (case when v.sign = '-' then current_date - v.due::interval else current_date + v.due::interval end)::date, NULL, v.verified, v.status, (now() - interval '9 days')
  FROM (VALUES
        ('DU', 'demo.rifat.du@campus360.test', '6c4bc788-45df-5729-93d5-ac4aa4d7951d'::uuid, 'Monsoon relief for DU students from Kurigram', 'Flood relief', 'Twenty-one students in our department lost stored grain and furniture to Jamuna erosion. The hall union is sending Tk 5,000 per family, and the disbursement list stays on the notice board with each receipt photographed. Nobody is asked to post a sad photograph; donor names appear in the ledger only if the donor wants them there.', 350000, 214500, 96, '25 days', '+', true, 'ACTIVE'),
        ('BUET', 'demo.sabbir.buet@campus360.test', 'a86b3747-9f6a-57b0-9ad2-53f60c1ad0d7'::uuid, 'Shahid Smriti Hall common room fans and lights', 'Hall infrastructure', 'Six ceiling fans and twelve tube lights in the common room have been dead since summer, and the hall office has no budget head for it. Students pooled money for the water purifier last term and it was finished in eleven days, so we are doing that again. The contractor quote is attached to the ledger.', 120000, 71500, 41, '15 days', '+', true, 'ACTIVE'),
        ('RU', 'demo.sumaiya.ru@campus360.test', 'db6bebcc-debf-567b-abac-2b2ca19fa40b'::uuid, U&'Emergency medical fund \2014 RU student with dengue', 'Medical emergency', 'A third-year Bangla department student is in the ICCU with severe dengue and his family cannot cover the platelet and monitoring costs past Thursday. The hall office will pay the hospital directly and post the discharge bill, so no cash passes through any student''s hands.', 200000, 182000, 118, '2 days', '+', true, 'ACTIVE'),
        ('CU', 'demo.farzana.cu@campus360.test', '94ce4949-690e-5222-b139-0969382a1b84'::uuid, 'Registration and books support for 40 CU Commerce students', 'Scholarship fund', 'Forty students in our department could not register this term because they were Tk 3,000 to 6,000 short. We cover registration plus the used-book set, and the department''s financial officer verifies the income certificate before any disbursement.', 150000, 43500, 27, '40 days', '+', true, 'ACTIVE'),
        ('SUST', 'demo.rafiul.sust@campus360.test', 'b340f05e-840f-584c-88be-643fd853bf49'::uuid, 'SUST char-area students mess support (closed)', 'Flood relief', 'Completed and closed: thirty-four students from the Sunamganj char areas received a month of mess support after the flash flood. The final receipts are in the ledger, and the Tk 8,400 surplus was moved to the next campaign with donors'' consent rather than refunded across a hundred and forty small donors.', 250000, 250000, 152, '-4 days', '-', true, 'COMPLETED'),
        ('JUST', 'demo.tahmina.just@campus360.test', '75c0bb31-3bb0-5eb8-97d8-1ac8c7a868e1'::uuid, 'Blankets and warm clothes for day scholars', 'Winter relief', 'Day-scholar students cycle twelve kilometres at six in the morning in January. Forty blankets and thirty sweaters are needed. Collection points are the central library desk and the BBA counter; the distribution list is checked against the day-scholar register so this does not quietly become a giveaway.', 90000, 12500, 25, '30 days', '+', false, 'ACTIVE')
  ) AS v(campus_code, author_email, id, title, cause, story, target, raised, donors, due, sign, verified, status)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, story = EXCLUDED.story, cause = EXCLUDED.cause, target_bdt = EXCLUDED.target_bdt, raised_bdt = EXCLUDED.raised_bdt, donors_count = EXCLUDED.donors_count, deadline = EXCLUDED.deadline, cover_image_url = EXCLUDED.cover_image_url, is_verified = EXCLUDED.is_verified, status = EXCLUDED.status;,

  -- · donations (18 rows)
  INSERT INTO public.donations (id, university_id, donor_id, campaign_id, donor_name, amount_bdt, message, is_anonymous, status, created_at)
  SELECT v.id, u.id, pr.id, v.campaign_id::uuid, (select coalesce(au.raw_user_meta_data->>'full_name', 'Campus student') from auth.users au where au.id = pr.id), v.amount, v.message, v.anon, v.status, (now() - make_interval(days => 6 - v.n::int))
  FROM (VALUES
        ('DU', 'demo.tanvir.du@campus360.test', 'f2769bbf-57cc-54f3-9928-d0964308385a'::uuid, '6c4bc788-45df-5729-93d5-ac4aa4d7951d', '', 2500, 'From the CSE batch 22 floor of Fazlul Huq Muslim Hall.', false, 'CONFIRMED', 0),
        ('DU', 'demo.farhana.buet@campus360.test', '8f336910-e7e7-5ed6-8ab7-952accdc6f14'::uuid, '6c4bc788-45df-5729-93d5-ac4aa4d7951d', '', 1000, NULL, true, 'CONFIRMED', 1),
        ('DU', 'demo.mehedi.ru@campus360.test', 'c3bd2111-d2b6-53e2-9a1c-96646ee465b9'::uuid, '6c4bc788-45df-5729-93d5-ac4aa4d7951d', '', 500, 'Small amount this month, sorry. Please keep posting the receipts.', false, 'PLEDGED', 2),
        ('BUET', 'demo.tanvir.du@campus360.test', '723de0e3-5dab-51f7-b7db-2ee7f2fe3390'::uuid, 'a86b3747-9f6a-57b0-9ad2-53f60c1ad0d7', '', 2500, 'From the CSE batch 22 floor of Fazlul Huq Muslim Hall.', false, 'CONFIRMED', 0),
        ('BUET', 'demo.farhana.buet@campus360.test', 'a7c725e3-b14b-5d49-b25f-64ce0e8f5c3f'::uuid, 'a86b3747-9f6a-57b0-9ad2-53f60c1ad0d7', '', 1000, NULL, true, 'CONFIRMED', 1),
        ('BUET', 'demo.mehedi.ru@campus360.test', '10eaae1b-9d0c-5ed9-b9d5-9d186c92e3d6'::uuid, 'a86b3747-9f6a-57b0-9ad2-53f60c1ad0d7', '', 500, 'Small amount this month, sorry. Please keep posting the receipts.', false, 'PLEDGED', 2),
        ('RU', 'demo.tanvir.du@campus360.test', '9a00fdea-1683-5541-b930-3233ffa64045'::uuid, 'db6bebcc-debf-567b-abac-2b2ca19fa40b', '', 2500, 'From the CSE batch 22 floor of Fazlul Huq Muslim Hall.', false, 'CONFIRMED', 0),
        ('RU', 'demo.farhana.buet@campus360.test', '6b5510d5-74ca-5b7d-8612-50d838f2f350'::uuid, 'db6bebcc-debf-567b-abac-2b2ca19fa40b', '', 1000, NULL, true, 'CONFIRMED', 1),
        ('RU', 'demo.mehedi.ru@campus360.test', '8e162875-bb7f-5677-9377-e30bf800789d'::uuid, 'db6bebcc-debf-567b-abac-2b2ca19fa40b', '', 500, 'Small amount this month, sorry. Please keep posting the receipts.', false, 'PLEDGED', 2),
        ('CU', 'demo.tanvir.du@campus360.test', '6970db64-f89e-503c-95dc-f882cafc77a3'::uuid, '94ce4949-690e-5222-b139-0969382a1b84', '', 2500, 'From the CSE batch 22 floor of Fazlul Huq Muslim Hall.', false, 'CONFIRMED', 0),
        ('CU', 'demo.farhana.buet@campus360.test', 'be14d634-be40-5bd4-bcce-2576792494d8'::uuid, '94ce4949-690e-5222-b139-0969382a1b84', '', 1000, NULL, true, 'CONFIRMED', 1),
        ('CU', 'demo.mehedi.ru@campus360.test', '0b16e895-87b4-5729-873b-04158c19bc3a'::uuid, '94ce4949-690e-5222-b139-0969382a1b84', '', 500, 'Small amount this month, sorry. Please keep posting the receipts.', false, 'PLEDGED', 2),
        ('SUST', 'demo.tanvir.du@campus360.test', '03b35539-289d-57a4-ba92-e616517fa351'::uuid, 'b340f05e-840f-584c-88be-643fd853bf49', '', 2500, 'From the CSE batch 22 floor of Fazlul Huq Muslim Hall.', false, 'CONFIRMED', 0),
        ('SUST', 'demo.farhana.buet@campus360.test', '07128148-87c0-527f-b27c-166d692b0b9a'::uuid, 'b340f05e-840f-584c-88be-643fd853bf49', '', 1000, NULL, true, 'CONFIRMED', 1),
        ('SUST', 'demo.mehedi.ru@campus360.test', 'd018d961-b750-5a4e-b39e-0bd175e0d99a'::uuid, 'b340f05e-840f-584c-88be-643fd853bf49', '', 500, 'Small amount this month, sorry. Please keep posting the receipts.', false, 'PLEDGED', 2),
        ('JUST', 'demo.tanvir.du@campus360.test', '398e7ed6-4b2b-5cbd-9f06-22c11c2c3924'::uuid, '75c0bb31-3bb0-5eb8-97d8-1ac8c7a868e1', '', 2500, 'From the CSE batch 22 floor of Fazlul Huq Muslim Hall.', false, 'CONFIRMED', 0),
        ('JUST', 'demo.farhana.buet@campus360.test', 'd2220d2d-25c0-5660-880a-55e1d0c2381f'::uuid, '75c0bb31-3bb0-5eb8-97d8-1ac8c7a868e1', '', 1000, NULL, true, 'CONFIRMED', 1),
        ('JUST', 'demo.mehedi.ru@campus360.test', 'bd57a107-5392-51f6-8418-9e46d89ef524'::uuid, '75c0bb31-3bb0-5eb8-97d8-1ac8c7a868e1', '', 500, 'Small amount this month, sorry. Please keep posting the receipts.', false, 'PLEDGED', 2)
  ) AS v(campus_code, author_email, id, campaign_id, donor_name, amount, message, anon, status, n)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  ON CONFLICT (id) DO UPDATE SET campaign_id = EXCLUDED.campaign_id, donor_name = EXCLUDED.donor_name, amount_bdt = EXCLUDED.amount_bdt, message = EXCLUDED.message, is_anonymous = EXCLUDED.is_anonymous, status = EXCLUDED.status;,

  -- · donation_ledger (12 rows)
  INSERT INTO public.donation_ledger (id, university_id, campaign_id, entry_type, amount_bdt, description, proof_url)
  SELECT v.id, u.id, v.campaign_id::uuid, v.entry::text, v.amount, v.description, case when v.entry = 'DISBURSEMENT' then 'receipts/' || u.code || '/demo-ledger' else NULL end
  FROM (VALUES
        ('DU', 'demo.rifat.du@campus360.test', '90056551-c70b-58a2-8f95-5464688c5b15'::uuid, '6c4bc788-45df-5729-93d5-ac4aa4d7951d', 'DONATION', 71500, '32 donations received via bKash Nexus and the hall desk (batched summary).'),
        ('DU', 'demo.rifat.du@campus360.test', 'c1ce8356-85c8-5edb-87cf-358b5a89f4e6'::uuid, '6c4bc788-45df-5729-93d5-ac4aa4d7951d', 'DISBURSEMENT', 42900, 'Disbursement made against verified receipts; copies filed with the hall or department office.'),
        ('BUET', 'demo.sabbir.buet@campus360.test', '818e55b4-37cf-59cb-9173-a6493c605038'::uuid, 'a86b3747-9f6a-57b0-9ad2-53f60c1ad0d7', 'DONATION', 23833, '13 donations received via bKash Nexus and the hall desk (batched summary).'),
        ('BUET', 'demo.sabbir.buet@campus360.test', 'ba97499c-5961-5537-a8ba-7bdf7efe29e4'::uuid, 'a86b3747-9f6a-57b0-9ad2-53f60c1ad0d7', 'DISBURSEMENT', 14300, 'Disbursement made against verified receipts; copies filed with the hall or department office.'),
        ('RU', 'demo.sumaiya.ru@campus360.test', 'fd444d36-4772-5d01-98d2-7258eacfd374'::uuid, 'db6bebcc-debf-567b-abac-2b2ca19fa40b', 'DONATION', 60666, '39 donations received via bKash Nexus and the hall desk (batched summary).'),
        ('RU', 'demo.sumaiya.ru@campus360.test', 'cbcce64c-0c8e-5aab-ad54-206f362bc6be'::uuid, 'db6bebcc-debf-567b-abac-2b2ca19fa40b', 'DISBURSEMENT', 36400, 'Disbursement made against verified receipts; copies filed with the hall or department office.'),
        ('CU', 'demo.farzana.cu@campus360.test', '258e8578-c978-58c0-a50b-705ef6142ffc'::uuid, '94ce4949-690e-5222-b139-0969382a1b84', 'DONATION', 14500, '9 donations received via bKash Nexus and the hall desk (batched summary).'),
        ('CU', 'demo.farzana.cu@campus360.test', 'd481f307-922c-5193-9a9b-c44cf4bd737c'::uuid, '94ce4949-690e-5222-b139-0969382a1b84', 'DISBURSEMENT', 8700, 'Disbursement made against verified receipts; copies filed with the hall or department office.'),
        ('SUST', 'demo.rafiul.sust@campus360.test', '94a08ed4-994d-50c5-afea-eb6f5ca18864'::uuid, 'b340f05e-840f-584c-88be-643fd853bf49', 'DONATION', 83333, '50 donations received via bKash Nexus and the hall desk (batched summary).'),
        ('SUST', 'demo.rafiul.sust@campus360.test', '5ecf2966-3f75-501e-b1c2-406228532cb2'::uuid, 'b340f05e-840f-584c-88be-643fd853bf49', 'DISBURSEMENT', 50000, 'Disbursement made against verified receipts; copies filed with the hall or department office.'),
        ('JUST', 'demo.tahmina.just@campus360.test', 'c3888a5b-e0b6-599f-8e7e-3010ec6e55be'::uuid, '75c0bb31-3bb0-5eb8-97d8-1ac8c7a868e1', 'DONATION', 4166, '8 donations received via bKash Nexus and the hall desk (batched summary).'),
        ('JUST', 'demo.tahmina.just@campus360.test', '7a81a17e-0599-5657-bfc3-2ddcedf73a35'::uuid, '75c0bb31-3bb0-5eb8-97d8-1ac8c7a868e1', 'DISBURSEMENT', 2500, 'Disbursement made against verified receipts; copies filed with the hall or department office.')
  ) AS v(campus_code, author_email, id, campaign_id, entry, amount, description)
  JOIN public.universities u ON u.code = v.campus_code
  ON CONFLICT (id) DO UPDATE SET amount_bdt = EXCLUDED.amount_bdt, description = EXCLUDED.description, proof_url = EXCLUDED.proof_url;,

  -- · marketplace_listings (12 rows)
  INSERT INTO public.marketplace_listings (id, university_id, author_id, kind, title, description, category, price_bdt, condition, images, keyword_tags, is_negotiable, rent_period, views_count, status, created_at)
  SELECT v.id, u.id, pr.id, v.kind::public.listing_kind, v.title, v.descr, v.cat, v.price, upper(replace(v.cond, ' ', '_')), '{}'::text[], v.tags, v.nego, case when v.kind = 'RENT' then 'MONTHLY' else NULL end, v.views, 'AVAILABLE', (now() - interval '2 days')
  FROM (VALUES
        ('DU', 'demo.tanvir.du@campus360.test', 'a18780cf-56d8-51cc-b97d-44856f0404d9'::uuid, 'SELL', 'Casio fx-991EX calculator (2025 exam edition)', 'Books & Stationery', 1400, 'Good', 'Used for one admission season. The screen has a small scratch at the bottom that does not affect reading, and the battery cover is tight with no rattle. Handover at the TSC shade after 1pm.', ARRAY['calculator', 'admission', 'Casio']::text[], false, 214),
        ('DU', 'demo.nusrat.du@campus360.test', '1b7f999d-4048-588c-9955-d54d3fccbb2c'::uuid, 'SELL', 'Second-hand HSC English textbook set (1st and 2nd paper)', 'Books & Stationery', 350, 'Fair', 'Four books, no missing pages, some pencil notes in the grammar chapters which honestly help more than the books do. Collect from Begum Fazilatunnesa Mujib Hall gate; I am free after Asr.', ARRAY['HSC', 'English', 'textbook']::text[], false, 96),
        ('BUET', 'demo.sabbir.buet@campus360.test', 'b60ebab8-cbdf-59c8-8263-1e953f949bba'::uuid, 'RENT', 'Cycle for the semester (Phoenix, monthly rent)', 'Bicycle', 500, 'Good', 'Monthly rent with a lock and one spare tube included; deposit Tk 2,000 returned at the end of the semester. Ideal for the BUET-Farmgate stretch. Pickup from the Sher-e-Bangla Hall cycle stand.', ARRAY['cycle', 'rent', 'phoenix']::text[], true, 331),
        ('BUET', 'demo.farhana.buet@campus360.test', '8db2681c-9e2f-5874-97f0-d195f151f2f8'::uuid, 'SELL', 'Folding study table and chair (barely used)', 'Furniture', 1800, 'Like New', 'Bought for online classes during leave and never really used. Folds flat so it fits in a CNG. One screw is slightly bent but it holds. I can arrange delivery inside Agargaon for Tk 200.', ARRAY['study table', 'folding', 'chair']::text[], false, 152),
        ('RU', 'demo.mehedi.ru@campus360.test', 'd8862536-16e8-5467-bce9-14e1bfa26f49'::uuid, 'EXCHANGE', U&'HP laptop bag \2014 want a charger pouch instead', 'Gadget', 0, 'Good', 'Black HP sleeve, padded, zip fine. I only need a small charger pouch, so this is an exchange rather than a sale. Meet at the RU Central Mosque gate after Jummah.', ARRAY['laptop bag', 'exchange', 'charger']::text[], false, 74),
        ('RU', 'demo.sumaiya.ru@campus360.test', '43918dcc-aad0-57a8-8fb0-8228a36fa655'::uuid, 'WANTED', 'Any working used sewing machine for the mess', 'Furniture', 2500, 'Fair', U&'For the mess \2014 three of us will split it. It must work and be clean; a Singer U2 would be perfect but I will take anything that sews straight. Pickup from Kazla by cycle van.', ARRAY['sewing machine', 'mess', 'used']::text[], true, 41),
        ('CU', 'demo.imran.cu@campus360.test', '42b022d9-eed6-5161-902f-68b119fb148b'::uuid, 'SELL', 'Second-hand Android tablet (8 inch, 64GB) for classes', 'Electronics', 8500, 'Good', 'Battery health is around 88 per cent, the screen protector has been on since day one, and there is one corner dent you can feel. Comes with a stand and the original charger. Slightly negotiable after CU gate 2.', ARRAY['tablet', 'android', 'classes']::text[], true, 402),
        ('CU', 'demo.farzana.cu@campus360.test', '423d33a6-1bdc-53be-a1af-c815c61da304'::uuid, 'SELL', 'Kieso Intermediate Accounting volume 1 + calculator', 'Books & Stationery', 1200, 'Good', 'Volume 1 plus my Casio. Volume 2 is not included because I still need it for the final. Bundle price for a batchmate, and I will not split the two items.', ARRAY['accounting', 'kieso', 'calculator']::text[], false, 88),
        ('SUST', 'demo.rafiul.sust@campus360.test', '192370ad-9015-5ecf-80e9-68cf1194dbdd'::uuid, 'SELL', '22-inch LED monitor (working, no dead pixels)', 'Electronics', 5500, 'Good', 'Bought in 2023 for freelancing; selling because I moved to a laptop-only setup. HDMI and VGA both work, the stand is slightly loose but holds at an angle. Test it in my room before you pay anything.', ARRAY['monitor', 'LED', 'freelancing']::text[], false, 265),
        ('SUST', 'demo.sabrina.sust@campus360.test', 'ddd8560e-0e35-5817-9e5f-56268ffa34b2'::uuid, 'WANTED', 'Used gas stove and cylinder for a single room', 'Furniture', 3000, 'Fair', U&'For the room I share with my cousin. It must come with a valid safety sticker \2014 the one I saw at Zindabazar had a leaking valve so I walked away. Can collect by cycle van any evening.', ARRAY['gas stove', 'cylinder', 'room']::text[], true, 58),
        ('JUST', 'demo.alamin.just@campus360.test', 'b514466f-bbb5-564e-904e-6f63a18540ae'::uuid, 'SELL', 'Engineering drawing instrument rack (complete)', 'Gadget', 900, 'Like New', U&'Used for one semester of the drawing course, then I got a better set from home. Everything is inside: pens, ruling pens, two pencils and the T-square. Tk 900, no haggling \2014 I know what a new set costs.', ARRAY['drawing', 'instruments', 'engineering']::text[], false, 112),
        ('JUST', 'demo.tahmina.just@campus360.test', '07d47cf1-11ec-591f-b7b0-7a0b51117dc7'::uuid, 'EXCHANGE', 'Bangla literature books (RU/CU syllabus, 2022-24)', 'Books & Stationery', 0, 'Good', U&'Eight books from the last three semesters, all annotated. I want class notes for a course I missed, or any good objective English book \2014 fair trade, no cash either way.', ARRAY['bangla', 'literature', 'exchange']::text[], false, 39)
  ) AS v(campus_code, author_email, id, kind, title, cat, price, cond, descr, tags, nego, views)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  ON CONFLICT (id) DO UPDATE SET kind = EXCLUDED.kind, title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, price_bdt = EXCLUDED.price_bdt, condition = EXCLUDED.condition, images = EXCLUDED.images, keyword_tags = EXCLUDED.keyword_tags, is_negotiable = EXCLUDED.is_negotiable, rent_period = EXCLUDED.rent_period, views_count = EXCLUDED.views_count, status = EXCLUDED.status;,

  -- · reviews (21 rows)
  INSERT INTO public.reviews (id, university_id, author_id, target_type, target_id, rating, title, body, photo_urls, tags, verified_participation, pending_reports_count, is_hidden, created_at)
  SELECT v.id, u.id, pr.id, v.ttype::public.review_target_type, (case when v.tkind = 'menu' then ((select cm.id from public.cafeteria_menus cm where cm.university_id = u.id and cm.name_en = v.tgt limit 1)) when v.tkind = 'market' then ((select ml.id from public.marketplace_listings ml where ml.university_id = u.id and ml.title = v.tgt limit 1)) when v.tkind = 'donor' then ((select hd.id from public.health_donors hd where hd.university_id = u.id and hd.user_id = (select p8.id from public.profiles p8 where p8.email = v.tgt limit 1) limit 1)) when v.tkind = 'file' then ((select af.id from public.academic_files af where af.university_id = u.id and af.course_code = v.tgt limit 1)) when v.tkind = 'event' then ((select e.id from public.events e where e.university_id = u.id and e.title_en = v.tgt limit 1)) when v.tkind = 'ride' then ((select ro.id from public.rideshare_offers ro where ro.university_id = u.id and ro.origin = v.tgt limit 1)) when v.tkind = 'housing' then ((select hl.id from public.housing_listings hl where hl.university_id = u.id and hl.title = v.tgt limit 1)) when v.tkind = 'skill' then ((select sp.id from public.skill_postings sp where sp.university_id = u.id and sp.title = v.tgt limit 1)) when v.tkind = 'lost' then ((select li.id from public.lost_items li where li.university_id = u.id and li.title = v.tgt limit 1)) when v.tkind = 'club' then ((select c.id from public.clubs c where c.university_id = u.id order by c.created_at limit 1)) when v.tkind = 'notice' then ((select g.id from public.governance_notices g where g.university_id = u.id order by g.created_at desc limit 1)) end), v.rating, v.title, v.body, '{}'::text[], v.tags, v.verified, 0, false, (now() - interval '18 hours')
  FROM (VALUES
        ('DU', 'demo.farzana.cu@campus360.test', 'ebf542cd-24e8-5a56-93d8-7876061a1bc6'::uuid, 'HALL_DINING', 'menu', U&'Fazlul Huq Muslim Hall Mess \2014 Lunch', 3, 'Mess food improved, but the portions shrank', 'The beef curry is better seasoned than last term and the salad is actually fresh. But the rice quantity dropped and there is no refill line, which is a strange trade for the new rate. Average for hall food; not for Tk 92 a plate.', ARRAY['Portion', 'Taste', 'Hygiene']::text[], true),
        ('SUST', 'demo.tanvir.du@campus360.test', 'ca4aa73d-ab9b-51b9-a128-15691c18f463'::uuid, 'HALL_DINING', 'menu', U&'Shah Paran Hall Mess \2014 Lunch', 5, 'Rui on Thursday is worth the queue', 'Fish curry with aloo bhorta on Thursday is the reason I stay in the hall instead of eating outside. The kitchen keeps the counter clean and plates are washed in front of you, which killed my biggest complaint from last year.', ARRAY['Taste', 'Hygiene']::text[], true),
        ('BUET', 'demo.imran.cu@campus360.test', 'c7ba7048-82ae-5fe6-a92f-b43102aa3556'::uuid, 'MARKETPLACE', 'market', 'Cycle for the semester (Phoenix, monthly rent)', 5, 'Seller told the truth about battery health', 'The tablet came at 88 per cent as described, and the corner dent was exactly where he said it would be. That matters more than the price. He also waited twenty minutes at the gate because my class overran.', ARRAY['Honest', 'Patient']::text[], true),
        ('DU', 'demo.sabbir.buet@campus360.test', 'b5ad3eb6-3eba-5b9c-84f3-922e8130fa23'::uuid, 'MARKETPLACE', 'market', 'Casio fx-991EX calculator (2025 exam edition)', 4, 'Books as promised, one torn page I noticed after paying', 'The textbook set was honestly described and the grammar notes are useful. One page is torn in the second paper book. Ask about condition before you agree and it is a five-star listing.', ARRAY['Fair price']::text[], true),
        ('SUST', 'demo.nusrat.du@campus360.test', 'b4f59771-ebe3-5bff-bb9e-bb0683689cf1'::uuid, 'BLOOD_DONOR', 'donor', 'demo.rafiul.sust@campus360.test', 5, 'Arrived in forty minutes and stayed through the transfusion', 'He said he would come after class and he was there before we finished the paperwork. He stayed through the transfusion, took the donor slip and gave my family a copy. I do not have words for what that did for my father''s surgery timing.', ARRAY['Reliable', 'Urgent', 'Calm']::text[], true),
        ('RU', 'demo.sabrina.sust@campus360.test', '6e3a0700-5108-5ea5-9c2d-c77ad25747be'::uuid, 'BLOOD_DONOR', 'donor', 'demo.mehedi.ru@campus360.test', 4, U&'Genuine donor \2014 bring your own breakfast and time', 'She came to RMUH at 7am as agreed and donated without anyone chasing her. Only note: the blood bank queue is long and she left without waiting for the tea we arranged. Plan food and an hour either side.', ARRAY['Punctual']::text[], true),
        ('DU', 'demo.sumaiya.ru@campus360.test', 'e516c46b-4053-58e1-a338-0114d031f990'::uuid, 'ARCHIVE_FILE', 'file', 'CSE 3106', 4, 'Scans are legible; two pages of the 2019 paper are missing', 'The mid-term solutions alone are worth it for the normalization questions. The 2019 final has two pages photographed twice instead, so I lost twenty minutes working it out. Note it in the description and this is a five.', ARRAY['Useful', 'Legible']::text[], true),
        ('BUET', 'demo.rafiul.sust@campus360.test', 'a6746eb6-1d65-5072-97c0-e2b22a0815c6'::uuid, 'ARCHIVE_FILE', 'file', 'EEE 211', 5, 'The five-year EEE pack saved my spring', 'Every EEE 211 paper in one folder with the year on the page header. I printed it and worked through Sunday mornings only. Whoever compiled this deserves the upvote rather than a reputation for leaking questions.', ARRAY['Complete', 'Well organised']::text[], true),
        ('SUST', 'demo.alamin.just@campus360.test', 'f5abc87e-f472-528f-abc8-b4abe1b37df7'::uuid, 'ARCHIVE_FILE', 'file', 'CSE 3105', 3, 'Right content, half the pages scanned upside down', 'Useful sessional guide, but every other page is upside down and there is no OCR so searching the PDF does nothing. Fix the scanner settings and re-upload it as version two; the content deserves better.', ARRAY['Needs re-scan']::text[], false),
        ('DU', 'demo.mehedi.ru@campus360.test', 'a72d1f2d-8ea2-536b-988e-54822576f182'::uuid, 'EVENT', 'event', U&'DU Computer Society \2014 Web & Cloud Workshop 2026', 5, 'Packed by 10am and the Wi-Fi actually held', 'Registration took four minutes and the desk had spare name badges. The part I care about: they promised a hotspot for the live coding session and it held two hundred connections. Tea break on time; one speaker overran; everything else ran to schedule.', ARRAY['Smooth', 'Good internet']::text[], true),
        ('RU', 'demo.farhana.buet@campus360.test', 'bc913e1a-2422-508d-bb7e-42e92499f521'::uuid, 'EVENT', 'event', U&'RU Career Fair 2026 \2014 Business & Engineering', 4, 'The career fair was worth the CV printing money', 'Eighteen stands, and the two software firms took CVs on the spot instead of pointing at their website. The hall got hot after 1pm and sound feedback ruined the opening speech. Bring printed CVs, not a pen drive.', ARRAY['Employers actually hiring']::text[], true),
        ('DU', 'demo.tahmina.just@campus360.test', 'de5f886f-3f90-5a96-ad97-5fab660aa789'::uuid, 'TRANSPORTATION', 'ride', 'Mirpur 10 Bus Stand (opposite Shah Ali Mosque)', 5, 'Left Mirpur 10 exactly on time, no last-minute seat shuffle', 'He messaged the night before to confirm 7:50, arrived at 7:48, and did not try to squeeze a fifth person in after we were seated. AC worked, no music at volume, and the split was Tk 120 as listed.', ARRAY['Punctual', 'Fair split']::text[], true),
        ('CU', 'demo.rafiul.sust@campus360.test', '64260b4a-5f82-5ab6-8c6c-ae24f59685ef'::uuid, 'TRANSPORTATION', 'ride', 'Agrabad CDA Avenue 2 No. Bus Stop', 3, 'Tk 25 is fair, but he stopped twice for more passengers', 'The student rate is real and the microbus is the university one, but he picked up two more people at CRB and we reached the gate late for an 8:30 class. If you take this for a morning exam, sit at the front and be ready.', ARRAY['Cheap', 'Delayed']::text[], false),
        ('DU', 'demo.imran.cu@campus360.test', 'f641f994-ed0a-56d9-9f50-908a11124c29'::uuid, 'HOUSING', 'housing', 'Girls'' mess seat, two-sharing near Mirpur 10', 5, 'The room matched the photos; geyser fixed the same day', 'Moved into the Mirpur mess and the listing hid nothing, including the lift that works half the day. The geyser stopped on my second night and the plumber came by lunch. Rent was what the post said, with no surprise ''utility extra'' at the end.', ARRAY['Honest listing', 'Responsive']::text[], true),
        ('CU', 'demo.mehedi.ru@campus360.test', '2c571023-2c78-50cf-b673-78cec8efa8ee'::uuid, 'HOUSING', 'housing', U&'PG room for women students \2014 Khulshi, quiet building', 4, U&'Good PG for a commerce student \2014 the curfew is real', 'Attached bath is clean, dinner is on time, and the owner does not interrogate you about class schedules. The 10pm curfew is enforced: my friend came at 10:20 and had to call down. Know that before you take it if labs run late.', ARRAY['Safe', 'Quiet']::text[], true),
        ('SUST', 'demo.sabbir.buet@campus360.test', 'd935b92f-69f6-52b2-b087-79bf8b75f678'::uuid, 'TUTORING', 'skill', 'Programming tutor for SUST 1st/2nd year (C and Python)', 5, 'Two months of evening classes; calculus C to A-', U&'He did not just solve problems \2014 he made me close the book and re-derive the same integral on the whiteboard until it stopped looking like magic. Sessional prep was honest about what the department actually asks. Worth every taka.', ARRAY['Explains clearly', 'Exam focused']::text[], true),
        ('RU', 'demo.farzana.cu@campus360.test', '8da26ed6-46d7-5392-bbaa-4eea6b4f108a'::uuid, 'TUTORING', 'skill', 'Spoken English & IELTS crash course for RU students', 4, 'IELTS speaking practice that does not waste your hour', 'We spoke every class, he cut me off when I rambled and gave a band estimate with the reason. Writing Task 2 feedback came back inside two days with corrections in the document, not in chat. The room is basic, which is fine.', ARRAY['Speaking', 'Fast feedback']::text[], true),
        ('RU', 'demo.nusrat.du@campus360.test', '8e0afd90-bc9d-504a-9685-3478cbc1b482'::uuid, 'LOST_AND_FOUND', 'lost', U&'Men''s wallet with NIC and a bKash card \2014 Puja Market', 5, 'Wallet returned with every taka and the NIC inside', 'He could have taken the cash and thrown the wallet in Padra; instead he posted it the same night and handed it over at the security office with a written record. He refused the Tk 500 reward and said it is his hall''s rule, which I do not believe, but fine.', ARRAY['Trustworthy']::text[], true),
        ('DU', 'demo.alamin.just@campus360.test', 'fb8c575b-658c-58ca-89f3-ed205674443d'::uuid, 'LOST_AND_FOUND', 'lost', U&'DU student ID card \2014 CSE third year', 4, 'Got the calculator back after describing the sticker', 'The finder asked what sticker was inside the battery lid instead of handing it to the first person who messaged. That is a small thing and it is the whole point of a found post. Meet-up at TSC took two minutes.', ARRAY['Careful']::text[], true),
        ('DU', 'demo.shahriar.mentor@campus360.test', '98d47524-8e23-5088-bdd8-fd12f8690c25'::uuid, 'CLUBS', 'club', '', 5, 'The society actually runs its own workshops', 'I joined for the CV line and stayed because the Tuesday sessions are taught by final-year students who remember the coursework. No gatekeeping against non-CSE people, and the room booking was handled without me chasing anybody.', ARRAY['Welcoming']::text[], false),
        ('BUET', 'demo.sumaiya.ru@campus360.test', 'd702dad5-1799-5f25-b45b-a1bf24f6fe9a'::uuid, 'NOTICE_BOARD', 'notice', '', 4, 'A dated notice board beats the WhatsApp group', U&'Mess rate changes and gate timings stopped being rumours because they are posted with a date and a source. One improvement: push a notification for ration changes \2014 half the hall still learns them two days late at the canteen.', ARRAY['Accurate']::text[], true)
  ) AS v(campus_code, author_email, id, ttype, tkind, tgt, rating, title, body, tags, verified)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  ON CONFLICT (id) DO UPDATE SET rating = EXCLUDED.rating, title = EXCLUDED.title, body = EXCLUDED.body, tags = EXCLUDED.tags, verified_participation = EXCLUDED.verified_participation;,

  -- · governance_notices (6 rows)
  INSERT INTO public.governance_notices (id, university_id, title, body, audience, created_at, updated_at)
  SELECT v.id, u.id, v.title, v.body, v.audience::text, (now() - make_interval(days => v.age_days)), (now() - make_interval(days => v.age_days))
  FROM (VALUES
        ('DU', 'demo.tanvir.du@campus360.test', '09dafe33-8f7b-526e-8ff8-42dc07037fa7'::uuid, 'Autumn 2026 academic calendar and class start date', 'Classes for all honours and degree programmes begin on 6 December 2026. Registration for the shortened first semester runs 24 November to 3 December through the department office; no extension will be granted for late fee payment. Hall residents moving in on the notified dates must carry the hall allotment letter.', 'STUDENTS', 2),
        ('BUET', 'demo.sabbir.buet@campus360.test', 'b67ecf94-2742-5a3c-8b54-c19eb4b8b10e'::uuid, 'Hall mess ration rate revised effective 1 December', 'The hall administration committee has set the per-plate lunch rate at Tk 92 and dinner at Tk 88, with mess accounts published monthly on each hall notice board. Students in arrears beyond two months must clear the balance before next-term registration; an installment option exists at the accounts desk.', 'RESIDENTS', 4),
        ('RU', 'demo.mehedi.ru@campus360.test', '5214c7b7-727a-5a7e-b357-9036cfc9b1c8'::uuid, 'No academic activity on 14 and 15 November (notified public holiday)', 'In observance of the notified public holiday, all classes, labs and sessional assessments stand cancelled on 14 and 15 November. The central library and the medical centre remain open on reduced hours; hall gates follow the normal weekend schedule. Any make-up class must be approved by the department chairman in advance.', 'ALL', 6),
        ('CU', 'demo.imran.cu@campus360.test', '8377dafc-63e6-5c20-91f1-5a6f102fa1ec'::uuid, 'Lift maintenance in the CRB academic building, 8 to 12 November', 'Both lifts in the CRB academic building will be out of service from 8 to 12 November for scheduled maintenance; floors one to four are reachable by stairs only. Timetabled classes on higher floors are relocated to the ground-floor halls as listed on the department notice board. Students with mobility difficulty should contact the office of the Vice-Chancellor for arrangements.', 'ALL', 8),
        ('SUST', 'demo.rafiul.sust@campus360.test', '3d697075-8afb-5790-b002-2acfca73b100'::uuid, 'Heavy rain alert: leaving class early on flooded routes will not be marked absent', 'The campus disaster management cell instructs teachers not to mark students absent for leaving early when the Kumargaon and Panu ghat roads are waterlogged during the forecast period. Hall administration will arrange extra evening transport from the main gate. Residents should not attempt that route on foot or by bicycle in rising water.', 'STUDENTS', 10),
        ('JUST', 'demo.alamin.just@campus360.test', 'c5e25673-9c68-5f75-a528-3030f49e3507'::uuid, 'Day scholar card issuance and central library entry from 25 October', 'Day-scholar identity cards for the 2025-26 session are issued from the students'' office between 25 October and 8 November, 10:00am to 1:00pm. The card is required for central library entry and for the exam form. Students absent from the printed list should apply through the portal before the deadline.', 'STUDENTS', 12)
  ) AS v(campus_code, author_email, id, title, body, audience, age_days)
  JOIN public.universities u ON u.code = v.campus_code
  ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, audience = EXCLUDED.audience;,

  -- · club_notices (6 rows)
  INSERT INTO public.club_notices (id, university_id, author_id, club_id, title, body, created_at)
  SELECT v.id, u.id, pr.id, cl.id, v.title, v.body, (now() - make_interval(hours => v.age_hours))
  FROM (VALUES
        ('DU', 'demo.tanvir.du@campus360.test', '92f94451-ab09-5c67-91dc-3a69113f69a3'::uuid, 'cse-society', 'Web & Cloud Workshop series starts 18 November', 'Sessions run every Tuesday at 6pm in the TSC seminar room. Two facilitator slots are still open: if you finished the beginner track and want to teach, send your name with one line on what you would teach. Sign the attendance sheet at the door or the certificate cannot be issued.', 3),
        ('BUET', 'demo.sabbir.buet@campus360.test', '8e6f1e2d-70fc-5844-a968-2ce1a83f8dc5'::uuid, 'debate-club', U&'Practice rounds every Tuesday 5:30pm \2014 all departments welcome', 'Bangla parliamentary motion practice this month, English rounds from next week. Bring a printed copy of the motion; we do four rounds and two feedback sessions. Beginners are paired with a senior speaker so the first round is not wasted.', 7),
        ('RU', 'demo.mehedi.ru@campus360.test', '30f1b470-36f0-53c7-abf7-99657fd7e6af'::uuid, 'volunteer-network', 'Blood donation camp at Puja Market on 15 November', U&'We are staffing the camp from 10am to 4pm with the Rajshahi Medical College blood bank and need twelve volunteers in two shifts \2014 two hours each, plus one spare for the registration desk. Volunteers get a certificate from the club, which the hall office accepts for the cultural-activity credit.', 11),
        ('CU', 'demo.imran.cu@campus360.test', 'a6ab1a0a-e653-51e5-897d-81f8c6eb1d01'::uuid, 'photography-society', 'Monsoon photowalk to Agrabad, and the annual exhibition call', U&'We walk the old Agrabad streets on Saturday at 6:30am for the light before the heat, ending at the library side. Bring whatever you have \2014 a phone is fine. Prints for the annual exhibition must be submitted by 25 November, three per person maximum, with the location written on the back.', 15),
        ('SUST', 'demo.rafiul.sust@campus360.test', '788f7625-b9e3-5e71-a85b-836500fc4605'::uuid, 'cse-society', 'ICPC intra bootcamp and sessional project showcase', 'Three practice contests before the intra, Saturday mornings in the CSE lab, and the judges for the project showcase are final-year students plus one faculty. Register a team of three with a name; teams that miss a practice contest are not seeded, and we cannot make exceptions because the online judge queue gets jammed.', 19),
        ('JUST', 'demo.tahmina.just@campus360.test', '951a9258-1a84-56ef-a926-75d2bc4845e9'::uuid, 'debate-club', U&'Intra-JUST Bangla debate trials \2014 motion released now', 'The motion is published on the club notice so you can prepare for a week instead of an hour. Trials are on Thursday at 3pm in the seminar hall; eight speakers maximum this round because the room holds four podiums. Sign up at the debate club desk with your department and roll number.', 23)
  ) AS v(campus_code, author_email, id, slug, title, body, age_hours)
  JOIN public.universities u ON u.code = v.campus_code
  JOIN public.profiles pr ON pr.email = v.author_email
  JOIN LATERAL (select c.id from public.clubs c where c.university_id = u.id and c.slug = v.slug limit 1) cl on true
  ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body;,

  -- ---------------------------------------------------------------------
  -- 18 · denormalised counters, recomputed from the rows themselves so no card
  -- shows a number its own list contradicts.
  -- ---------------------------------------------------------------------
  UPDATE public.skill_postings sp SET applicants_count = sub.n
  FROM (SELECT sp2.id, count(sa.id)::int AS n FROM public.skill_postings sp2
        LEFT JOIN public.skill_applications sa ON sa.posting_id = sp2.id AND sa.status <> 'DECLINED'
        GROUP BY sp2.id) sub WHERE sub.id = sp.id;

  UPDATE public.events e SET rsvp_count = sub.n
  FROM (SELECT e2.id, count(r.id)::int AS n FROM public.events e2
        LEFT JOIN public.event_rsvps r ON r.event_id = e2.id AND r.status = 'GOING'
        GROUP BY e2.id) sub WHERE sub.id = e.id;

  UPDATE public.donation_campaigns dc SET raised_bdt = sub.raised, donors_count = sub.n
  FROM (SELECT dc2.id,
               coalesce(sum(dd.amount_bdt) FILTER (WHERE dd.status = 'CONFIRMED'), 0) AS raised,
               count(dd.id)::int AS n
        FROM public.donation_campaigns dc2
        LEFT JOIN public.donations dd ON dd.campaign_id = dc2.id
        GROUP BY dc2.id) sub WHERE sub.id = dc.id;

  UPDATE public.rideshare_offers ro SET seats_available = sub.n
  FROM (SELECT id, least(seats_total, greatest(0, seats_available)) AS n FROM public.rideshare_offers) sub
  WHERE sub.id = ro.id;

  DROP TABLE IF EXISTS tmp_person;
END
$$;
